BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('kcna-q1', 'Kubernetesとは何か',
   '動かすコンテナの数が数個から数百個に増えたとき、1つ1つのコンテナをどのサーバーで動かすか・落ちたら誰が気づくかを人手で管理するのが難しくなる。この問題を解決するためにKubernetesのような仕組みが担う役割は何か。',
   NULL::text,
   '["大量のコンテナの起動・配置・再起動をまとめて自動で管理すること", "コンテナの中身のプログラムの実行速度そのものを引き上げること", "コンテナが使うネットワーク通信をすべて自動的に暗号化すること", "サーバーのハードディスクの空き容量を自動的に増やしていくこと"]',
   0, '[0]', 'single',
   '{"asked": "コンテナが大量になったときKubernetesが解決する問題を問う問題。", "point": "Kubernetesの正体は「大量のコンテナを人手ではなく自動でまとめて管理する仕組み」。", "kid": "コンテナが1つや2つなら手で管理できるけど、何百個にもなると「どれがどこで動いてる」「落ちたのはどれ」を人間が追いきれなくなる。Kubernetesはその管理をコンピュータに肩代わりさせる仕組み。", "eg": "小さい子ども1人のお世話は1人の親でできるけど、100人の子どもを預かる保育園には、名簿を作って全体を見渡す園長のような役割が要る。Kubernetesはその園長にあたる。", "terms": [["オーケストレーション", "多数のコンテナの起動・配置・監視をまとめて自動で行うこと"], ["コンテナ", "アプリと必要なものを1つにまとめた、軽量に動かせる実行環境（linux-basicsで既習）"]], "think": "なぜ「自動化」が要るのかがカギ。コンテナの数が増えるほど、どのサーバーに空きがあるか、どれが落ちているかといった管理の手間は数に比例して増えていく。人間が確認する速度には限界があるので、これをソフトウェアに常時見張らせて自動でさばく仕組みが必要になる。Kubernetesはこの「見張って、必要なら手を打つ」という役目を担う。", "vs": "「Kubernetesはコンテナを速くする道具」という誤解に注意。速度そのものを上げる仕組みではなく、あくまで多数のコンテナの管理・配置を自動化する仕組み。", "usecase": "QA目線では、テスト環境を何十個も並行して立てたいとき、1つ1つ手で作ると管理しきれない。Kubernetesのような仕組みがあれば、必要な数のテスト環境をまとめて自動で用意・破棄できる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"60\" height=\"24\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"50.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">A</text><rect x=\"90\" y=\"20\" width=\"60\" height=\"24\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"120.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">B</text><rect x=\"160\" y=\"20\" width=\"60\" height=\"24\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"190.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">C</text><rect x=\"230\" y=\"20\" width=\"60\" height=\"24\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"260.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">D</text><text x=\"170\" y=\"12\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナが大量に…</text><line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"72\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 66 L 170 72 L 174 66\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"70\" y=\"72\" width=\"200\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"85\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Kubernetes</text><text x=\"170.0\" y=\"101\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（自動でまとめて管理）</text><text x=\"170\" y=\"128\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">起動・配置・再起動を人手からコンピュータへ</text></svg>", "opt": ["正解。大量のコンテナの起動・配置・再起動を自動でまとめて管理するのがKubernetesの役割。", "コンテナ内のプログラム自体の実行速度を上げる機能ではない。管理・配置が役目。", "通信の暗号化は別の専用の仕組み（ネットワークポリシーやTLSなど）が担う領域で、Kubernetes自体の主目的ではない。", "ディスク容量を自動で増やす機能ではない。あくまでコンテナの配置・管理が役目。"]}'),

  ('kcna-q2', 'Kubernetesとは何か',
   'コンテナがあるサーバー（ノード）でいくつか動いていたが、そのサーバー自体が突然故障して止まってしまった。Kubernetesを使っていた場合、一般にどう対応されるか。',
   NULL::text,
   '["Kubernetesが故障を検知し、正常な別のノードで同じ内容のコンテナを自動的に立て直す", "故障したノードが自動的に修理され、元通り動き出すまで他のコンテナはすべて待たされる", "その故障をきっかけに、クラスタ全体のコンテナがすべていったん停止させられる", "故障したノードの中身のデータだけが、自動で別サーバーのハードディスクへコピーされる"]',
   0, '[0]', 'single',
   '{"asked": "ノード故障時にKubernetesがどう振る舞うかを問う問題。", "point": "壊れた場所を直すのではなく、正常な場所に新しく作り直すという発想。", "kid": "サーバーが1台壊れても、Kubernetesは「壊れたサーバーを直す」のではなく、「他の元気なサーバーで同じコンテナをもう一度作り直す」ことで、動いているように見せかけ続けてくれる。", "eg": "お店の1つの支店が停電で閉まってしまったら、店長（Kubernetes）はすぐ直そうとするより先に、別の支店に同じ品ぞろえの臨時店舗をすぐ開かせる、というイメージ。", "terms": [["ノード", "コンテナが実際に動くサーバー1台1台のこと"], ["セルフヒーリング", "落ちたコンテナを検知して自動的に作り直す仕組み"]], "think": "なぜ「壊れた場所を直す」より「別の場所に作り直す」なのかがカギ。物理的なハードウェア故障はKubernetes自身では直せない。だからKubernetesは「あるべき数のコンテナが動いている状態」を保つことだけに専念し、足りなくなったら正常な別のノードに新しく作ることで帳尻を合わせる。この考え方（あるべき姿を保ち続ける）はDeploymentなど、あとで学ぶ多くの仕組みの土台になる。", "vs": "「Kubernetesがハードウェアを直接修理する」という誤解に注意。ハードウェア修理は人間や別のシステムの仕事で、Kubernetesはあくまでソフトウェア（コンテナ）の配置をやりくりするだけ。", "usecase": "QA目線では、テスト実行中にエージェントの1台が落ちても、Kubernetes環境なら別のノードでテストコンテナが自動的に立て直され、テスト全体が止まりにくい。", "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"75.0\" y=\"31\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ノードA</text><text x=\"75.0\" y=\"46\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（故障）</text><rect x=\"220\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"265.0\" y=\"31\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ノードB</text><text x=\"265.0\" y=\"46\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（正常）</text><text x=\"170\" y=\"15\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナが動いていた</text><line x1=\"120\" y1=\"70\" x2=\"210\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 204 66 L 210 70 L 204 74\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"165\" y=\"63\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">作り直す</text><rect x=\"235\" y=\"60\" width=\"60\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"265.0\" y=\"76\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">新コンテナ</text><text x=\"170\" y=\"130\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">壊れた場所は直さず、正常な場所に新しく作る</text></svg>", "opt": ["正解。故障を検知し、正常な別のノードで同じ内容のコンテナを自動的に立て直す。", "Kubernetes自身が物理的なハードウェア故障を修理する機能は持たない。修理を待つ間動き続けるための仕組みが立て直しである。", "1つのノードの故障でクラスタ全体を止める動作はしない。むしろ影響を局所化して動き続けさせるのが狙い。", "データの自動コピーはVolumeなど別の仕組みの話で、ノード故障時の基本動作としてまず起きるのはコンテナの立て直し。"]}'),

  ('kcna-q3', 'Kubernetesとは何か',
   'オーケストラでは、演奏者それぞれが自分の楽器を鳴らすだけでなく、指揮者が全体を見てテンポや入りのタイミングを揃えている。Kubernetesを使ったコンテナ運用にこの例えを当てはめると、指揮者の役割に最も近いのはどれか。',
   NULL::text,
   '["個々のコンテナがバラバラに動かないよう、全体の配置やタイミングをまとめて指示するKubernetes自身", "演奏者にあたる、それぞれ自分の処理に専念しているコンテナ1つ1つそのもの", "演奏の様子を録音して記録に残すだけの、監視やログ収集を担う周辺の仕組み", "演奏会場そのものにあたる、コンテナが実際に動いている物理サーバーのハードウェア"]',
   0, '[0]', 'single',
   '{"asked": "オーケストラの比喩でKubernetesの役割がどこに当たるかを問う問題。", "point": "個々の演奏者（コンテナ）を直接鳴らすのではなく、全体を見て指示を出す立場が指揮者＝Kubernetes。", "kid": "演奏者（コンテナ）は自分の楽器を鳴らすことに集中していて、いつどのタイミングで入るか・誰が休むかといった全体の調整は指揮者が見ている。Kubernetesも同じように、個々のコンテナの中身には立ち入らず、「どこで何個動かすか」という全体の調整役に徹する。", "eg": "指揮者は誰かの楽器を代わりに演奏するわけではなく、あくまで全体のタイミングを揃える役目。Kubernetesもコンテナの中のアプリの処理そのものはせず、配置とタイミングの調整に専念する。", "terms": [["オーケストレーション", "全体を見て調整する役目。オーケストラの指揮に由来する言葉"]], "think": "なぜこの比喩が「役割の分担」を表しているのかがカギ。演奏者（コンテナ）は自分の演奏（アプリの処理）に専念し、指揮者（Kubernetes）は全体のタイミングや配置の調整に専念する、という役割分担が本質。どちらか一方が両方をやろうとすると破綻する（演奏者が指揮もすると個々の演奏がおろそかになる）。", "vs": "「指揮者＝一番偉い演奏者」という誤解に注意。指揮者は演奏そのものはしない、別の役割（調整役）である点が本質。Kubernetesもアプリの処理そのものは行わない。", "usecase": "QA目線では、多数の自動テストジョブを「誰がいつどのマシンで走るか」調整する役回りが、この指揮者の役割に近い。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"15\" width=\"100\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">指揮者 = Kubernetes</text><line x1=\"140\" y1=\"43\" x2=\"140\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 136 54 L 140 60 L 144 54\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"43\" x2=\"170\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 54 L 170 60 L 174 54\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"200\" y1=\"43\" x2=\"200\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 196 54 L 200 60 L 204 54\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"110\" y=\"62\" width=\"40\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"130.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">演奏者A</text><rect x=\"150\" y=\"62\" width=\"40\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">演奏者B</text><rect x=\"190\" y=\"62\" width=\"40\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"210.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">演奏者C</text><text x=\"170\" y=\"108\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ = 演奏者（自分の処理に専念）</text></svg>", "opt": ["正解。個々のコンテナの中身には立ち入らず、全体の配置とタイミングを調整するのがKubernetesの役割。", "演奏者にあたるのはコンテナ側。指揮者ではなく調整される側である。", "監視・ログの仕組みは録音や記録に近く、全体のタイミングを指示する指揮そのものではない。", "会場（ハードウェア）はコンテナが実際に動く場所であり、調整の指示を出す側ではない。"]}'),

  ('kcna-q4', 'Kubernetesとは何か',
   'DockerとKubernetesはよく一緒に語られるが、両者の役割の違いとして最も適切なものはどれか。',
   NULL::text,
   '["Dockerは1つのコンテナを作って動かす道具、Kubernetesは複数のコンテナを複数のサーバーにまたがってまとめて管理する仕組み", "DockerとKubernetesは実装が違うだけで機能はまったく同じで、呼び方が違うだけの同一のソフトウェアである", "KubernetesはDockerの内部だけで使われる、画面表示のためだけの小さな補助部品にすぎない", "Dockerは複数サーバーを扱う上級者向け、Kubernetesは1台のPCだけで動かす初心者向けという難易度だけの違いである"]',
   0, '[0]', 'single',
   '{"asked": "DockerとKubernetesの役割の違いを問う問題。", "point": "Dockerは「1つ作って動かす」道具、Kubernetesは「たくさんをまたがって管理する」仕組み。両者は対立ではなく役割の階層が違う。", "kid": "Dockerは1つのコンテナを作って手元で動かすための道具。Kubernetesは、そうやって作られたコンテナを何十個・何百個、複数のサーバーにまたがって「どこで何個動かすか」を管理する、もう一段上の仕組み。", "eg": "Dockerが「1台の車を組み立てる工場」だとすると、Kubernetesは「たくさんの車をどの道路にどう走らせるかを差配する交通管制システム」に近い。", "terms": [["コンテナランタイム", "コンテナを実際に起動・実行する部品。Dockerが代表例"], ["オーケストレーション", "多数のコンテナの配置・管理をまとめて行う役割"]], "think": "なぜ両者が対立ではなく階層関係なのかがカギ。Dockerのようなコンテナランタイムは「1つのコンテナをどう起動するか」を担当し、Kubernetesは「どのサーバーにいくつ、どのタイミングで配置するか」というより広い範囲の管理を担当する。KubernetesはコンテナランタイムそのものというよりComplete a step above it, その上に乗って全体を差配する立場になる。", "vs": "「Kubernetesを使えばDockerは不要になる」という単純な置き換えの誤解に注意。KubernetesはDockerに代わる存在というより、Dockerのようなコンテナ実行の仕組みを土台にして、その上で大量のコンテナをまとめて管理する層である。", "usecase": "QA目線では、手元でDockerを使って1つのテスト環境を作る経験はあっても、それを何十個も複数マシンにまたがって管理する場面でKubernetesの価値が出てくる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"180\" y=\"15\" width=\"140\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"250.0\" y=\"26\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Kubernetes</text><text x=\"250.0\" y=\"41\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（複数コンテナ・複数サーバーの管理）</text><line x1=\"250\" y1=\"45\" x2=\"250\" y2=\"62\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 246 56 L 250 62 L 254 56\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"180\" y=\"62\" width=\"140\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"250.0\" y=\"73\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Docker等</text><text x=\"250.0\" y=\"88\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（1つのコンテナを作って動かす）</text><rect x=\"20\" y=\"15\" width=\"130\" height=\"77\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"85.0\" y=\"50\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">役割は階層が違う</text><text x=\"85.0\" y=\"64\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">対立関係ではない</text></svg>", "opt": ["正解。Dockerは1つのコンテナを作って動かす道具、Kubernetesは複数のコンテナを複数サーバーにまたがって管理する仕組み。", "担当する範囲が異なる別々のソフトウェアであり、同一機能の呼び方違いではない。", "Kubernetesは画面表示の部品ではなく、多数のコンテナの配置・管理を担う独立した仕組みである。", "難易度の違いではなく、担当する役割の範囲（1つを動かす／たくさんを管理する）が異なる。"]}'),

  ('kcna-q5', 'Kubernetesとは何か',
   'Kubernetesには「namespace」という言葉があり、Linuxにも同じ「namespace」という言葉がある（linux-basicsの`コンテナの正体`で既習）。この2つの関係として正しいものはどれか。',
   NULL::text,
   '["「区切る」という発想は似ているが、Kubernetesのnamespaceはクラスタ内のリソースの区分け、Linuxのnamespaceはプロセスの隔離機構という別の仕組みである", "まったく同じ1つの機能を指しており、KubernetesのnamespaceはLinuxのnamespaceの呼び出しをそのまま流用しているだけの機能である", "Kubernetesのnamespaceは、Linuxのnamespaceの機能をすべて完全に置き換える上位互換の新しい機能である", "Linuxのnamespaceという用語自体がKubernetesの世界には存在せず、両者はまったく無関係などちらか一方にしかない言葉である"]',
   0, '[0]', 'single',
   '{"asked": "KubernetesのnamespaceとLinuxのnamespaceの関係を問う問題。", "point": "名前は同じでも中身は別物。「区切る」という発想の共通点はあるが、区切る対象のレイヤーが違う。", "kid": "Linuxのnamespaceは、1台のコンピュータの中でプロセスが見える範囲を区切って独立させる仕組み（コンテナが互いに干渉しないようにする土台）。一方Kubernetesのnamespaceは、クラスタという広い場所の中で「開発チーム用」「テストチーム用」のようにリソースをグループ分けして整理する仕組み。同じ「区切る」でも、区切っている対象のレベルが違う。", "eg": "Linuxのnamespaceが「1つの建物の中の各部屋の壁」だとすると、Kubernetesのnamespaceは「1つの街の中の区画（○○区・△△区）」に近い。どちらも「区切る」けれど、扱っているスケールがまったく違う。", "terms": [["Linuxのnamespace", "1台のコンピュータの中でプロセスの見える範囲を区切る仕組み（linux-basics既習）"], ["Kubernetesのnamespace", "クラスタ内のリソース（PodやServiceなど）を論理的にグループ分けする仕組み"]], "think": "なぜこの2つを混同しやすいのかがカギ。どちらも「区切って独立させる」という発想は共通しているため名前が同じになったが、Linuxのnamespaceはコンテナ1つ1つを実現するための低レベルな仕組み、Kubernetesのnamespaceはクラスタ全体という高いレベルでリソースを整理整頓するための仕組みで、扱う階層がまったく違う。この違いを区別できると、「Kubernetesのnamespaceを消してもコンテナの隔離自体は壊れない」という直感も持てる。", "vs": "「同じ単語だから同じ機能」という思い込みに注意。名前の由来（区切る）は共通でも、対象のレイヤー（1台のPC内のプロセス vs クラスタ内のリソース）が異なる別の仕組み。", "usecase": "QA目線では、同じクラスタの中に「開発用」「テスト用」「本番検証用」のnamespaceを分けて作ることで、テスト環境同士が名前や設定でぶつからないように整理できる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"140\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"90.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Linuxのnamespace</text><text x=\"90.0\" y=\"51\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1台のPC内でプロセスを区切る</text><rect x=\"180\" y=\"20\" width=\"140\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"250.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Kubernetesのnamespace</text><text x=\"250.0\" y=\"51\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">クラスタ内でリソースを区切る</text><text x=\"170\" y=\"15\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「区切る」発想は似ているが対象のレベルが違う</text><line x1=\"20\" y1=\"75\" x2=\"320\" y2=\"75\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"170\" y=\"100\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">低レベル（プロセス） vs 高レベル（クラスタのリソース）</text></svg>", "opt": ["正解。発想は似ているが、Kubernetesのnamespaceはクラスタ内のリソースの区分け、Linuxのnamespaceはプロセスの隔離機構という別の仕組み。", "同じ単語ではあるが、対象とするレイヤーが異なる別々の仕組みであり、片方が片方をそのまま呼び出しているわけではない。", "上位互換で置き換える関係ではなく、そもそも扱う対象のレベルが異なる別の仕組みである。", "どちらの世界にも「namespace」という同じ言葉があり、無関係というより「発想は似ているが対象が違う別物」という関係が正確。"]}'),

  ('kcna-q6', 'クラスタの構造（コントロールプレーンとノード）',
   'Kubernetesの「クラスタ」は、大きく2種類のマシンの集まりでできている。その2種類の正しい組み合わせはどれか。',
   NULL::text,
   '["全体を管理・判断するコントロールプレーンと、実際にコンテナが動くワーカーノード", "普段使いの本番用サーバーと、緊急時に備えるバックアップ用サーバーの2種類", "国内に置かれたサーバーと、海外に置かれたサーバーという地理的な区分の2種類", "料金を払う有料プランのサーバーと、無料プランのサーバーという契約上の2種類"]',
   0, '[0]', 'single',
   '{"asked": "クラスタを構成する2種類のマシンの組み合わせを問う問題。", "point": "クラスタ＝「頭脳（コントロールプレーン）」＋「手足（ワーカーノード）」の集まり。", "kid": "クラスタというのは、たくさんのサーバーが集まって1つのKubernetes環境を作っているもの。その中には、全体の状況を把握して指示を出す「コントロールプレーン」というマシン群と、実際にコンテナが動く「ワーカーノード」というマシン群の、大きく2種類がある。", "eg": "会社にたとえると、コントロールプレーンは本部（指示を出す場所）、ワーカーノードは各支店（実際に接客するお店）。本部で決めたことを支店が実行する関係に近い。", "terms": [["コントロールプレーン", "クラスタ全体を管理・判断する頭脳役のマシン群"], ["ワーカーノード", "実際にPod（コンテナ）が動く手足役のマシン群"]], "think": "なぜ2種類に分けるのかがカギ。「どこに何を配置するか決める仕事」と「実際にコンテナを動かす仕事」を同じマシンで全部やろうとすると役割が混ざって管理しにくい。判断する側（コントロールプレーン）と実行する側（ワーカーノード）を分けることで、指示系統がはっきりし、ワーカーノードを増減させても指示の出し方は変わらないという柔軟さも生まれる。", "vs": "「クラスタ＝1台の巨大なサーバー」という誤解に注意。実際には役割の違う複数台のマシンの集まりであり、1台に見えても内部は分業している。", "usecase": "QA目線では、テスト環境の規模を大きくしたいとき、ワーカーノードだけを増やせばコンテナを動かす余力が増える、という考え方に直結する。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"90\" y=\"15\" width=\"160\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"34\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コントロールプレーン（頭脳）</text><line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"62\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 56 L 170 62 L 174 56\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"30\" y=\"62\" width=\"90\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"75.0\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ワーカーノード</text><text x=\"75.0\" y=\"90\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（手足）</text><rect x=\"220\" y=\"62\" width=\"90\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"265.0\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ワーカーノード</text><text x=\"265.0\" y=\"90\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（手足）</text><text x=\"170\" y=\"112\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">指示する側と、実際に動く側に分かれている</text></svg>", "opt": ["正解。全体を管理・判断するコントロールプレーンと、実際にコンテナが動くワーカーノードの2種類でクラスタが構成される。", "本番用・バックアップ用という運用上の区分ではなく、役割そのもの（管理する側／動かす側）が異なる2種類のマシン群である。", "地域による区分ではなく、担当する役割（管理／実行）による区分である。", "料金プランによる区分ではなく、担当する役割（管理／実行）による区分である。"]}'),

  ('kcna-q7', 'クラスタの構造（コントロールプレーンとノード）',
   'kubectlでコマンドを打ったり、コントロールプレーン内の他の部品同士がやり取りしたりするとき、必ず窓口として経由するコンポーネントはどれか。',
   NULL::text,
   '["APIサーバー", "etcd", "kubelet", "コンテナランタイム"]',
   0, '[0]', 'single',
   '{"asked": "クラスタ内のすべてのやり取りが経由する唯一の窓口を問う問題。", "point": "誰と話すにもまずAPIサーバー。クラスタの中で唯一の正式な玄関口。", "kid": "kubectlからの命令も、コントロールプレーンの中の他の部品同士の会話も、すべてAPIサーバーという1つの窓口を通る。「誰かに何か頼みたいなら、まずAPIサーバーに声をかける」という決まりになっている。", "eg": "会社の代表電話（APIサーバー）を思い浮かべるとよい。外部からの問い合わせも、社内の部署同士の連絡も、まずは代表電話（受付）を経由してつながる、というイメージ。", "terms": [["APIサーバー", "クラスタへのすべての操作・問い合わせが経由する唯一の窓口"], ["kubectl", "APIサーバーに命令を送るためのコマンドラインの道具"]], "think": "なぜ窓口を1つに絞るのかがカギ。もし色々な部品が好き勝手にお互いへ直接命令できてしまうと、誰が何をいつ変更したのか追いきれなくなり、矛盾した指示が飛び交う恐れがある。APIサーバーという単一の窓口に絞ることで、すべての操作を一元的に受け付け、認証・検証をそこで一括して行える。この「唯一の窓口」という設計は、以降のカテゴリで学ぶkubectlやコントローラの動きすべての前提になる。", "vs": "「kubectlが直接コンテナを操作している」という誤解に注意。kubectlは命令をAPIサーバーに送るだけの道具であり、実際にコンテナへ手を出すのはAPIサーバー経由で別のコンポーネント（kubeletなど）が行う。", "usecase": "QA目線では、クラスタの操作ログを追うとき、まずAPIサーバーへのリクエスト履歴を見れば「誰が何を指示したか」が一元的に分かる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"55\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"60.0\" y=\"74\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">kubectl</text><line x1=\"100\" y1=\"70\" x2=\"140\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 134 66 L 140 70 L 134 74\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"140\" y=\"40\" width=\"100\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"190.0\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">APIサーバー</text><text x=\"190.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（唯一の窓口）</text><line x1=\"240\" y1=\"55\" x2=\"280\" y2=\"55\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 274 51 L 280 55 L 274 59\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"240\" y1=\"85\" x2=\"280\" y2=\"85\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 274 81 L 280 85 L 274 89\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"275\" y=\"40\" width=\"55\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"302.5\" y=\"56\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">etcd</text><rect x=\"275\" y=\"72\" width=\"55\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"302.5\" y=\"88\" font-size=\"7\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">他の部品</text></svg>", "opt": ["正解。kubectlも、コントロールプレーン内の他の部品同士も、すべてAPIサーバーという唯一の窓口を経由する。", "etcdは情報の保管庫であり、外部からの操作はまずAPIサーバーが受け付けてからetcdに読み書きする。", "kubeletは各ワーカーノードでの実行役であり、外部からの命令の唯一の窓口ではない。", "コンテナランタイムは実際にコンテナを起動する部品で、クラスタ全体の命令の窓口ではない。"]}'),

  ('kcna-q8', 'クラスタの構造（コントロールプレーンとノード）',
   '「クラスタのあるべき状態（どのPodが何個動くべきか等）」を記録している、いわば正の情報源として使われるコンポーネントはどれか。',
   NULL::text,
   '["etcd", "kubectl", "kubelet", "kube-proxy"]',
   0, '[0]', 'single',
   '{"asked": "クラスタの状態を記録する正の情報源を問う問題。", "point": "クラスタの「今どうなっているべきか」の記録帳がetcd。", "kid": "クラスタの中には「今どんなPodが何個あるべきか」といった情報を書き留めておく記録帳のような場所があり、それがetcd。他の部品は困ったらこの記録帳を見に行く。", "eg": "図書館の蔵書目録（etcd）のようなもの。どの本が何冊あるはずか、という正式な記録がそこにまとまっていて、司書（他のコンポーネント）はその目録を見て動く。", "terms": [["etcd", "クラスタの状態を記録する、正の情報源となるデータベース"]], "think": "なぜ「正の情報源」が1か所に必要なのかがカギ。もし複数の場所にバラバラに「あるべき状態」の情報があると、どれが正しいか分からなくなり、部品同士の判断が食い違う恐れがある。etcdという1つの記録帳に情報を集約することで、どの部品も同じ「正解」を参照でき、クラスタ全体の判断がぶれない。この「1つの正の情報源」という考え方は、次のカテゴリで学ぶ宣言的管理（あるべき姿を書く）の土台にもなる。", "vs": "「kubectlが状態を保持している」という誤解に注意。kubectlは命令を送るだけの道具で、状態そのものはetcdに保存されている。", "usecase": "QA目線では、クラスタの状態を調べるとき、直接etcdを触ることは通常しないが、「どこかに正の情報源が1つあるはず」という発想は障害調査の見立てに役立つ。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"15\" width=\"100\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"34\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">APIサーバー</text><line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"62\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 56 L 170 62 L 174 56\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"120\" y=\"62\" width=\"100\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170.0\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">etcd</text><text x=\"170.0\" y=\"90\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（あるべき状態の記録帳）</text><text x=\"170\" y=\"108\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">他の部品はAPIサーバー経由でここを参照する</text></svg>", "opt": ["正解。クラスタのあるべき状態を記録する正の情報源はetcd。", "kubectlは命令をAPIサーバーへ送る道具であり、状態そのものを保存する場所ではない。", "kubeletは各ノードでコンテナを実際に動かす実行役で、クラスタ全体の記録帳ではない。", "kube-proxyはネットワークの転送を担う部品で、クラスタ全体のあるべき状態を保存する場所ではない。"]}'),

  ('kcna-q9', 'クラスタの構造（コントロールプレーンとノード）',
   '各ワーカーノードに1つずつ配置され、「このノードでこのPodが指定どおりに動いているか」を確認し、必要なら実際にコンテナランタイムへ起動・停止を指示するコンポーネントはどれか。',
   NULL::text,
   '["kubelet", "スケジューラ", "APIサーバー", "etcd"]',
   0, '[0]', 'single',
   '{"asked": "各ノードで実際にPodの状態を見張り、コンテナランタイムに指示する部品を問う問題。", "point": "各ノードの「現場監督」がkubelet。指示を受けて、実際にコンテナを動かす手配をする。", "kid": "各ワーカーノードには、そのノード専属の現場監督のような部品kubeletがいる。kubeletは「このノードではこのPodがこの状態で動くべき」という指示を受け取り、実際にコンテナランタイムへ「起動して」「止めて」と手配し、うまくいっているか見張り続ける。", "eg": "工事現場の現場監督（kubelet）のようなもの。本部（コントロールプレーン）からの設計図の指示を受けて、実際に現場の職人（コンテナランタイム）に作業を指示し、進み具合を見守る。", "terms": [["kubelet", "各ワーカーノードに常駐し、Podの状態を見張って実行を手配するコンポーネント"], ["コンテナランタイム", "実際にコンテナを起動・停止する実行部品"]], "think": "なぜノードごとに専属の見張り役が必要なのかがカギ。コントロールプレーンは全体の司令塔だが、1台1台のノードの細かい状態まですべて直接見に行くのは非効率。各ノードにkubeletという専属の見張り役を置くことで、ノードごとの状態確認と実行の手配をその場で完結させられる。kubeletは定期的にコントロールプレーンへ「今このノードはこの状態です」と報告もする。", "vs": "「kubeletがコンテナを直接動かしている」という誤解に注意。実際にコンテナを起動するのはコンテナランタイムで、kubeletはその実行を「指示・監督する」役割を担う。", "usecase": "QA目線では、あるノードだけでPodが正しく起動しないとき、まずそのノードのkubeletのログを見ると、原因の手がかりが得られやすい。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"15\" width=\"100\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コントロールプレーン</text><line x1=\"170\" y1=\"41\" x2=\"170\" y2=\"58\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 52 L 170 58 L 174 52\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"30\" y=\"58\" width=\"280\" height=\"32\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170.0\" y=\"78\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">kubelet（ノード専属の現場監督）</text><line x1=\"170\" y1=\"90\" x2=\"170\" y2=\"107\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 101 L 170 107 L 174 101\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"120\" y=\"107\" width=\"100\" height=\"20\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170.0\" y=\"120\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナランタイム</text></svg>", "opt": ["正解。各ノードに常駐し、Podの状態を確認しながらコンテナランタイムへ実行を指示するのがkubelet。", "スケジューラは新しいPodをどのノードに配置するか決める役割で、配置後の現場での見張りはkubeletが担う。", "APIサーバーはクラスタ全体の窓口であり、1台のノードに専属で常駐する現場監督ではない。", "etcdは状態を記録する記録帳であり、現場でコンテナランタイムに指示を出す役割ではない。"]}'),

  ('kcna-q10', 'クラスタの構造（コントロールプレーンとノード）',
   '新しいPodをどこで動かすか決めるとき、「どのノードに空きリソースがあるか」を判断して配置先を決めるコンポーネントはどれか。',
   NULL::text,
   '["スケジューラ", "kube-proxy", "kubelet", "etcd"]',
   0, '[0]', 'single',
   '{"asked": "新しいPodの配置先ノードを判断するコンポーネントを問う問題。", "point": "「どこに置くか決める」のがスケジューラ、「決まった場所で実際に動かす」のがkubelet。役割が分かれている。", "kid": "新しいPodを作ろうとするとき、「どのノードなら空きがあって置けそうか」を考えて配置先を決めるのがスケジューラ。決まったあとで実際にそのノードでコンテナを動かす仕事は、そのノードのkubeletが引き継ぐ。", "eg": "引っ越し先を決める不動産の案内係（スケジューラ）と、実際に荷物を運び入れる引っ越し業者（kubelet）の関係に近い。案内係は「この部屋が空いています」と決めるだけで、実際の荷入れはしない。", "terms": [["スケジューラ", "新しいPodをどのノードに配置するか決めるコンポーネント"], ["リソース", "CPUやメモリなど、ノードが持つ処理能力の余力"]], "think": "なぜ「決める役」と「動かす役」を分けるのかがカギ。配置を決めるには全ノードの空き状況を見渡す必要があり、実際に動かすには1台のノードに専念する必要がある。この2つの視点（全体を見渡す／1台に専念する）は性質が違うため、スケジューラ（全体を見て決める）とkubelet（1台で実行する）という別々のコンポーネントに分けられている。", "vs": "「スケジューラが実際にコンテナを起動する」という誤解に注意。スケジューラは配置先を決めるところまでで、実行そのものはそのノードのkubeletとコンテナランタイムが担う。", "usecase": "QA目線では、特定のノードにばかりテスト用Podが偏って詰まってしまうような不具合を調査するとき、スケジューラの配置判断の仕組みを理解しておくと原因を追いやすい。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"15\" width=\"100\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"25\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">スケジューラ</text><text x=\"170.0\" y=\"40\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（配置先を決める）</text><line x1=\"170\" y1=\"43\" x2=\"170\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 54 L 170 60 L 174 54\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"30\" y=\"60\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"75.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ノードA(空)</text><rect x=\"220\" y=\"60\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"265.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ノードB(混雑)</text><text x=\"170\" y=\"105\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">空きのあるノードAに配置を決める</text></svg>", "opt": ["正解。新しいPodをどのノードに配置するか、空きリソースを見て判断するのがスケジューラ。", "kube-proxyはネットワークの転送ルールを管理する部品で、Podの配置先を決める役割ではない。", "kubeletは配置が決まったあとそのノードで実際に実行・監督する役割で、配置先そのものを決める役割ではない。", "etcdは状態の記録帳であり、配置先を能動的に判断する役割ではない。"]}'),

  ('kcna-q11', 'Podという最小単位',
   'Kubernetesではコンテナを直接デプロイするのではなく、「Pod」という単位でデプロイする。Podとは何か、最も適切な説明はどれか。',
   NULL::text,
   '["1つ以上のコンテナをまとめ、ネットワークやストレージを共有させる、Kubernetesにおける最小のデプロイ単位", "コンテナの実行速度を全体的に引き上げるために使われる専用のキャッシュの仕組みのこと", "複数台のノードをまとめて束ね、1つの巨大なサーバーのように見せかける仮想化の仕組み", "クラスタ全体で発生したログをまとめて1か所に集めて保存しておくための記録装置のこと"]',
   0, '[0]', 'single',
   '{"asked": "Podの定義そのものを問う問題。", "point": "Podは「コンテナの入れ物」。1つ以上のコンテナをひとまとめにして、ネットワークやストレージを共有させる単位。", "kid": "Kubernetesは、コンテナをそのままバラバラに配置するのではなく、1つ以上のコンテナをひとまとめにした「Pod」という箱に入れてから配置する。同じPodの中のコンテナ同士は、ネットワークやストレージを共有できる。", "eg": "Podは「同じ弁当箱に入ったおかず」のようなもの。おかず（コンテナ）は複数あっても、同じ弁当箱（Pod）の中にいる限り一緒に運ばれ、同じ箱の中身は他のおかずとも触れ合える。", "terms": [["Pod", "1つ以上のコンテナをまとめた、Kubernetesにおける最小のデプロイ単位"]], "think": "なぜコンテナを直接ではなくPodという単位で扱うのかがカギ。密接に協力し合う複数のコンテナ（例えば本体のアプリと、そのログを転送する補助役）は、同じネットワークやストレージを共有できたほうが都合がよい場面がある。Podという「入れ物」を用意することで、そうした密接な組み合わせを1つの単位としてまとめて配置・管理できるようになる。", "vs": "「Pod＝コンテナの言い換えにすぎない」という誤解に注意。1つのPodに1つのコンテナだけを入れる使い方は多いが、Podはあくまで「入れ物」であり、コンテナそのものとは別の概念。", "usecase": "QA目線では、テスト対象のアプリコンテナと、テスト結果を横で収集する補助コンテナを同じPodにまとめる、といった構成を考えるときにこの概念が直接関わってくる。", "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"15\" font-size=\"10\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">Pod（入れ物）</text><rect x=\"60\" y=\"25\" width=\"220\" height=\"80\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><rect x=\"90\" y=\"60\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"125.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナA</text><rect x=\"180\" y=\"60\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"215.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナB</text><text x=\"170\" y=\"45\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ネットワーク・ストレージを共有</text><text x=\"170\" y=\"120\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Podが最小のデプロイ単位</text></svg>", "opt": ["正解。1つ以上のコンテナをまとめ、ネットワークやストレージを共有させる、最小のデプロイ単位がPod。", "コンテナを高速化するキャッシュ機能ではなく、コンテナをまとめる入れ物としての概念である。", "複数ノードをまとめた仮想サーバーではなく、コンテナをまとめる単位であり、ノードとは別の階層の話。", "ログを集める記録装置ではなく、コンテナのデプロイ単位を表す概念である。"]}'),

  ('kcna-q12', 'Podという最小単位',
   '1つのPodの中に、メインのアプリのコンテナと、そのログを外部へ転送する補助的なコンテナの2つを入れて動かした。この2つのコンテナの関係として正しいものはどれか。',
   NULL::text,
   '["同じPod内なので、同じネットワーク（同じIP）とストレージを共有し、互いにlocalhost相当で通信できる", "同じPod内であっても、それぞれ完全に別のIPアドレスを持ち、インターネット経由でしか通信できない", "同じPod内のコンテナは自動的に1つのコンテナへ合体してしまい、互いの区別がなくなる", "同じPod内のコンテナは、常に片方が起動している間はもう片方が起動できない仕組みになっている"]',
   0, '[0]', 'single',
   '{"asked": "同じPod内の複数コンテナがネットワーク・ストレージをどう共有するかを問う問題。", "point": "同じPod内のコンテナは、同じIP・同じストレージを共有する「同居人」。", "kid": "同じPodの中に入っているコンテナ同士は、同じ家（Pod）に住んでいる同居人のようなもの。同じ玄関（IPアドレス）を使い、隣の部屋（localhost）にいるように直接話しかけられる。", "eg": "1つのマンションの部屋（Pod）にルームメイト（コンテナ）が2人住んでいて、同じ郵便受け（IP）を共有し、部屋の中では大声で呼びかけずとも会話できる、というイメージ。", "terms": [["localhost", "同じPod内でコンテナ同士が通信するときに使う、自分自身を指すアドレス"], ["サイドカーパターン", "メインのコンテナを補助する役目のコンテナを同じPodに同居させる構成の呼び名"]], "think": "なぜ同じPod内なら同じネットワークを共有できるのかがカギ。Podという入れ物を用意する目的の1つが、密接に協力するコンテナ同士を同じネットワーク空間・同じストレージに置けるようにすることだった。そのため同じPod内のコンテナは、まるで同じマシン上の別プロセスであるかのように、localhost経由で手軽に通信できる。この仕組みがあるからこそ、メインのアプリと補助役（ログ転送など）を分けて作りつつ、密に連携させられる。", "vs": "「別々のPodのコンテナ同士もlocalhostで話せる」という誤解に注意。localhost相当の直接通信ができるのは同じPod内に限られ、別々のPod同士はService等の別の仕組みを介して通信する。", "usecase": "QA目線では、アプリ本体のPodにテスト用の監視コンテナを同居させ、localhost経由でアプリの内部状態を手軽に取得する、といった構成に応用できる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" font-size=\"9\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">Pod（同じIP・同じストレージ）</text><rect x=\"50\" y=\"26\" width=\"240\" height=\"74\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><rect x=\"80\" y=\"60\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"120.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">メインアプリ</text><rect x=\"200\" y=\"60\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"240.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ログ転送役</text><line x1=\"160\" y1=\"75\" x2=\"200\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 194 71 L 200 75 L 194 79\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"46\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">localhost経由で直接通信</text></svg>", "opt": ["正解。同じPod内のコンテナは同じIP・同じストレージを共有し、localhost相当で直接通信できる。", "別々のIPを持ちインターネット経由でしか話せないのは別々のPod同士の場合であり、同じPod内はそうではない。", "同じPod内でも各コンテナは独立したプロセスとして区別され、自動的に1つに合体することはない。", "同じPod内の複数コンテナは同時に起動して動くのが基本であり、片方しか起動できない制約はない。"]}'),

  ('kcna-q13', 'Podという最小単位',
   'あるPodが何らかの理由で再作成された（元のPodが消えて、新しいPodが作られた）とき、Podが持つIPアドレスはどうなるか。',
   NULL::text,
   '["新しいPodには新しいIPアドレスが割り当てられ、以前と同じとは限らない", "元のPodと完全に同じIPアドレスが必ず引き継がれる", "IPアドレスという概念はPodには存在せず、常にノードのIPだけが使われる", "IPアドレスはPodが起動している間ずっと変化し続け、数秒おきに変わる"]',
   0, '[0]', 'single',
   '{"asked": "Podが再作成されたときIPアドレスがどうなるかを問う問題。", "point": "Podは使い捨て。再作成されると別物として扱われ、IPも変わりうる。", "kid": "Podは「同じ名前でも中身は新品」に作り直される使い捨ての存在。だから、あるPodが消えて新しいPodが作られると、IPアドレスも新しいものになることが多く、前と同じ番地とは限らない。", "eg": "同じ番号の部屋（Pod名）でも、一度取り壊して建て直すと、郵便番号や住所表記（IP）が新しくなることがある、というイメージに近い。", "terms": [["エフェメラル", "使い捨てで、いつ消えて作り直されてもおかしくない性質"]], "think": "なぜIPが変わってしまうことが問題になりうるのかがカギ。もしアプリが「特定のIPアドレス」を直接覚えて通信していたら、Podが再作成されるたびに接続先を書き換えなければならず、非常に不便で壊れやすい。この「PodのIPは変わりうる」という性質があるからこそ、次のカテゴリで学ぶService（安定した窓口）のような仕組みが必要になる。", "vs": "「Podは長期間同じ場所・同じIPで動き続けるもの」という誤解に注意。PodはVMのように長生きする前提の存在ではなく、いつでも作り直されうる使い捨ての単位として設計されている。", "usecase": "QA目線では、テスト自動化のスクリプトの中にPodのIPアドレスを直接ハードコードしてしまうと、Podが再作成されるたびにテストが壊れる、という典型的な落とし穴につながる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"25\" width=\"115\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"77.5\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod（旧）</text><text x=\"77.5\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">IP: 10.0.0.5</text><text x=\"77\" y=\"78\" font-size=\"9\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">消える</text><line x1=\"150\" y1=\"45\" x2=\"200\" y2=\"45\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 194 41 L 200 45 L 194 49\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"200\" y=\"25\" width=\"115\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"257.5\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod（新）</text><text x=\"257.5\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">IP: 10.0.0.9</text><text x=\"170\" y=\"105\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">再作成されるとIPは変わりうる（使い捨て）</text></svg>", "opt": ["正解。Podは使い捨てで、再作成されると新しいIPアドレスが割り当てられ、以前と同じとは限らない。", "IPアドレスが必ず引き継がれる保証はなく、変わることを前提に扱う必要がある。", "PodにもIPアドレスの概念は存在し、ノードのIPとは別にPod自身のIPを持つ。", "起動中に常時変わり続けるわけではなく、そのPodが動いている間は同じIPを保つ。変わりうるのは再作成されたときである。"]}'),

  ('kcna-q14', 'Podという最小単位',
   '「Pod」と「コンテナ」という2つの言葉の関係を、最も正確に説明しているものはどれか。',
   NULL::text,
   '["Podはコンテナをまとめる入れ物であり、コンテナそのものではない。1つのPodに複数のコンテナが入ることもある", "PodとコンテナはKubernetesの中では完全に同じものを指しており、単なる呼び方の違いにすぎない", "逆にコンテナのほうがPodを内部に複数持つという、入れ子になった構造になっている", "Podは常にちょうど1つのコンテナしか入れられない箱であり、コンテナと1対1の関係にしかならない"]',
   0, '[0]', 'single',
   '{"asked": "PodとコンテナというKubernetes学習でもっとも混同されやすい2語の関係を問う問題。", "point": "Podは箱、コンテナは中身。1つの箱に複数の中身が入ることもある、という主従関係。", "kid": "Podは箱、コンテナはその箱の中に入っている中身。箱（Pod）の中にはコンテナが1つのこともあれば、複数入っていることもある。「Pod＝コンテナの言い換え」ではなく、Podはコンテナを入れるための一段上の入れ物。", "eg": "Podは弁当箱、コンテナはその中のおかず。弁当箱（Pod）1つにおかず（コンテナ）が1品だけのこともあれば、複数品入っていることもある、というイメージ。", "terms": [["Pod", "1つ以上のコンテナをまとめる、Kubernetesの最小デプロイ単位"], ["コンテナ", "実際にアプリが動く実行環境そのもの"]], "think": "なぜこの2つを混同しやすいのかがカギ。実務では1つのPodに1つのコンテナだけを入れる使い方が非常に多いため、体感として「Pod＝コンテナ」に感じやすい。しかし1対1で使うことが多いだけであって、仕組みとしてはPodという入れ物の中にコンテナが1つ以上入る、という主従関係が正しい。この区別を持っておくと、複数コンテナを同居させる構成（サイドカーパターンなど）に出会ったときに戸惑わずに理解できる。", "vs": "「1つのPodには必ず1つのコンテナしか入らない」という思い込みに注意。実際には複数のコンテナを同居させることもできる（前の設問のログ転送役の例）。", "usecase": "QA目線では、障害調査で「Podは動いているのにアプリが応答しない」という状況に出会ったとき、Pod内の複数コンテナのうちどれが不調かを個別に切り分けて調べる発想につながる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"15\" font-size=\"10\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">Pod（入れ物）</text><rect x=\"60\" y=\"25\" width=\"220\" height=\"80\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><rect x=\"90\" y=\"60\" width=\"60\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"120.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ</text><rect x=\"190\" y=\"60\" width=\"60\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"220.0\" y=\"71\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ</text><text x=\"220.0\" y=\"85\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(省略可)</text><text x=\"170\" y=\"46\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Podの中にコンテナが1つ以上</text></svg>", "opt": ["正解。Podはコンテナをまとめる入れ物であり、1つのPodに複数のコンテナが入ることもある。", "完全に同じものの呼び方違いではなく、入れ物（Pod）と中身（コンテナ）という別の階層の概念である。", "コンテナがPodを内部に持つ入れ子ではなく、逆にPodがコンテナを内部に持つ関係である。", "1つのPodに複数のコンテナを入れることも可能であり、常に1対1に限られるわけではない。"]}'),

  ('kcna-q15', 'Podという最小単位',
   '動いているPodの中身のコンテナがエラーで壊れてしまった場合、Kubernetesの基本的な考え方として最も近い対応はどれか。',
   NULL::text,
   '["壊れた場所を内部から修理するのではなく、Pod自体を新しく作り直して置き換える", "壊れたコンテナの中に入って、原因のファイルだけをKubernetesが自動的に手作業で書き換えて直す", "壊れたPodはそのまま放置され、二度と自動では対応されない", "壊れたPodのIPアドレスだけを変更すれば自動的に修復される"]',
   0, '[0]', 'single',
   '{"asked": "壊れたPodへのKubernetesの基本的な対応方針を問う問題。", "point": "Podは「直す」対象ではなく「作り直す」対象。使い捨てという性質の実務的な帰結。", "kid": "Podは長く使う修理前提の存在ではなく、壊れたら中を直そうとせず、新しく作り直して入れ替える、という考え方でKubernetesは動いている。", "eg": "使い捨てカイロが冷めたら、中身を温め直すのではなく新しいカイロに交換するのに近い。壊れたPodも同様に、直すより新しく作り直すほうが速くて確実。", "terms": [["エフェメラル", "使い捨てで、いつ消えて作り直されてもおかしくない性質（前の設問で既習）"]], "think": "なぜ「直す」より「作り直す」なのかがカギ。壊れたコンテナの内部を調べて原因箇所だけをピンポイントで直すのは、時間がかかるうえに確実性も低い。それよりも「正常な状態のPodをもう一つ新しく作る」ほうが、速くて結果も予測しやすい。この考え方は、以前学んだノード故障時の対応（別のノードで作り直す）や、次のカテゴリで学ぶReplicaSet/Deploymentのセルフヒーリングとも一貫している。", "vs": "「壊れたPodの中を自動で修理してくれる」という誤解に注意。Kubernetesは壊れた中身を直接修理する機能は持たず、あくまで「作り直す」ことで正常な状態に戻す。", "usecase": "QA目線では、テスト環境のPodが不安定になったとき、内部を粘って調査するより先に、Podを作り直して再現するかどうかを試すのが定石になる。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"30\" width=\"110\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"85.0\" y=\"54\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">壊れたPod</text><text x=\"85\" y=\"82\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">修理しない</text><line x1=\"150\" y1=\"50\" x2=\"200\" y2=\"50\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 194 46 L 200 50 L 194 54\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"200\" y=\"30\" width=\"110\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"255.0\" y=\"46\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">新しいPod</text><text x=\"255.0\" y=\"61\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（作り直し）</text></svg>", "opt": ["正解。壊れた場所を内部から修理するのではなく、Pod自体を新しく作り直して置き換える。", "Kubernetesはコンテナ内部のファイルを自動で手作業修理する機能は持たない。作り直すのが基本方針である。", "放置されるわけではなく、コントローラ（次のカテゴリで学ぶ仕組み）が検知して自動的に作り直しの対応をする。", "IPアドレスだけを変えても中身の壊れたコンテナが直るわけではない。作り直しが必要になる。"]}'),

  ('kcna-q16', '宣言的な管理とkubectl',
   '「Podを1つ起動して」「次にネットワーク設定して」と手順を1つずつ命令していく管理方法と、「常にPodが3つ動いている状態にしたい」というゴールだけを書いて、そこへの到達はKubernetesに任せる管理方法がある。後者を何と呼ぶか。',
   NULL::text,
   '["宣言的な管理", "命令的な管理", "手続き的な管理", "対話的な管理"]',
   0, '[0]', 'single',
   '{"asked": "「あるべき姿だけを書く」管理方法の名前を問う問題。", "point": "手順を1つずつ指図するのが命令的、ゴールだけ書いて任せるのが宣言的。Kubernetesは後者が基本。", "kid": "「まずこれをやって、次にこれをやって」と手順を1つずつ細かく指示するのが命令的な管理。逆に「最終的にこうなっていてほしい」というゴールだけを書いて、そこにたどり着く方法自体はKubernetesに任せるのが宣言的な管理。Kubernetesは基本的に後者のやり方で動く。", "eg": "料理でたとえると、命令的は「まず鍋を火にかけて、次に塩を入れて…」と手順を細かく指示するレシピ。宣言的は「塩味のスープが1つできている状態にして」とゴールだけ伝えて、作り方はシェフ（Kubernetes）に任せるイメージ。", "terms": [["宣言的", "最終的なあるべき姿（ゴール）だけを書き、そこへの到達方法は任せる考え方"], ["命令的", "手順を1つずつ具体的に指示していく考え方"]], "think": "なぜKubernetesは宣言的なやり方を基本にしているのかがカギ。命令的なやり方だと、途中で何かが失敗したときに「どこまで進んだか」を管理する側が毎回把握し直す必要があり手間がかかる。宣言的なやり方なら「あるべき姿」さえ書いておけば、途中で何が起きても、Kubernetesが今の状態とあるべき姿を見比べて、自動的に差分を埋めてくれる。この発想が次に学ぶ「コントロールループ」の土台になる。", "vs": "「宣言的＝何もしなくていい」という誤解に注意。あるべき姿を書く作業自体は必要で、そこから先の細かい手順の実行だけをKubernetesに任せる、という違い。", "usecase": "QA目線では、テストのアサーション（「最終的にこの状態になっているべき」という期待値の書き方）に近い発想。手順の検証ではなく、あるべき結果を検証する考え方と通じる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"140\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"90.0\" y=\"33\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">命令的</text><text x=\"90.0\" y=\"48\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手順を1つずつ指示</text><rect x=\"180\" y=\"20\" width=\"140\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"250.0\" y=\"33\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">宣言的</text><text x=\"250.0\" y=\"48\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ゴールだけ書く</text><text x=\"90\" y=\"70\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「まず○○、次に△△…」</text><text x=\"250\" y=\"70\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「常に3個動いている状態」</text><text x=\"170\" y=\"100\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Kubernetesは基本的に宣言的な管理を使う</text></svg>", "opt": ["正解。ゴールだけを書き、到達方法はKubernetesに任せる管理方法が宣言的な管理。", "命令的な管理は手順を1つずつ指示していくやり方で、設問が指すゴールだけを書く方法とは逆。", "手続き的という言葉は一般に命令的な管理と近い意味で使われ、ゴールだけを書く方法を指す一般的な用語ではない。", "対話的は1つずつやり取りしながら進める意味合いが強く、ゴールだけを宣言する方法を指す一般的な用語ではない。"]}'),

  ('kcna-q17', '宣言的な管理とkubectl',
   '「Podを3つ動かしたい」というあるべき状態をYAML形式のファイルに書いて、それをKubernetesに渡す。この設定ファイルのことを一般に何と呼ぶか。',
   NULL::text,
   '["マニフェスト", "スクリプト", "パッチノート", "ログファイル"]',
   0, '[0]', 'single',
   '{"asked": "あるべき状態を書いたYAMLファイルの呼び名を問う問題。", "point": "あるべき状態を書いた設計図がマニフェスト。宣言的管理の「宣言」の中身そのもの。", "kid": "「Podを3つ動かしたい」のような、あるべき状態をYAMLという書式で書いたファイルをマニフェストと呼ぶ。これがKubernetesへの「こうなっていてほしい」という宣言そのもの。", "eg": "マニフェストは、家を建てるときの設計図のようなもの。「こういう間取りの家にしたい」という完成形を書いておき、実際に建てる作業（大工の手順）は別の人（Kubernetes）に任せる。", "terms": [["マニフェスト", "あるべき状態をYAML形式で記述した設定ファイル"], ["YAML", "設定を人間が読み書きしやすい形式で書くための記法"]], "think": "なぜ手順書ではなく設計図（マニフェスト）を書くのかがカギ。前の設問で学んだ「宣言的な管理」を実際に行うには、あるべき姿を何らかの形で書き記す必要がある。その書き記す先がマニフェストというYAMLファイル。手順を1行ずつ書くスクリプトとは違い、マニフェストには「最終的にこうなっていてほしい」という状態だけが書かれ、そこへの到達手順はKubernetes側の仕事になる。", "vs": "「マニフェスト＝実行される手順の羅列」という誤解に注意。手順ではなく、あるべき状態（ゴール）を書く点がシェルスクリプトのような手続き型のファイルとの違い。", "usecase": "QA目線では、テスト環境を毎回同じ構成で再現したいとき、そのマニフェストをそのままバージョン管理しておけば、いつでも同じ環境を宣言的に再現できる。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"25\" width=\"130\" height=\"55\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"95.0\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">マニフェスト(YAML)</text><text x=\"95.0\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「Podを3つ</text><text x=\"95.0\" y=\"71\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">動かしたい」</text><line x1=\"170\" y1=\"52\" x2=\"220\" y2=\"52\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 214 48 L 220 52 L 214 56\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"220\" y=\"25\" width=\"100\" height=\"55\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"270.0\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Kubernetes</text><text x=\"270.0\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">が到達方法を</text><text x=\"270.0\" y=\"71\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">考えて実行</text></svg>", "opt": ["正解。あるべき状態をYAML形式で書いた設定ファイルをマニフェストと呼ぶ。", "スクリプトは手順を1つずつ実行させる命令的な書き方を指すことが多く、あるべき状態を宣言するマニフェストとは性質が異なる。", "パッチノートは変更点の説明文書であり、あるべき状態を宣言する設定ファイルではない。", "ログファイルは起きた出来事の記録であり、あるべき状態を事前に宣言するものではない。"]}'),

  ('kcna-q18', '宣言的な管理とkubectl',
   'kubectlコマンドを実行したとき、実際に起きていることの説明として最も正確なものはどれか。',
   NULL::text,
   '["kubectlはコマンドの内容をAPIサーバーへの命令に変換して送るだけの窓口であり、コンテナを直接操作しているわけではない", "kubectlはコンテナランタイムへ直接命令を送り込み、コンテナを自らの手で起動・停止させている", "kubectlはコマンドを実行するたびに、クラスタ全体をいったん1から作り直している", "kubectlはetcdの中身を直接書き換えることで、クラスタの状態を更新している"]',
   0, '[0]', 'single',
   '{"asked": "kubectlを実行したときの実際の動きを問う問題。", "point": "kubectlは「APIサーバーに話しかけるだけの窓口係」。自分で何かを直接動かしているわけではない。", "kid": "kubectlは、打ち込んだコマンドをAPIサーバーへの正式なお願いの形に変換して送るだけの道具。コンテナを自分の手で直接動かしているわけではなく、あくまで「お願いを届ける係」。", "eg": "kubectlは、注文を厨房（クラスタの内部）に伝えるだけのウェイター（受付係）のようなもの。ウェイター自身が料理（コンテナの実行）をするわけではない。", "terms": [["kubectl", "APIサーバーに命令を送るためのコマンドラインの道具"], ["client", "サーバーにお願いを送る側のプログラム。kubectlはAPIサーバーのclientにあたる"]], "think": "なぜkubectl自身が何もしないのかがカギ。以前学んだ「すべてのやり取りはAPIサーバーという唯一の窓口を通る」という原則がここでも成り立つ。kubectlは特別な裏口を持っておらず、他のあらゆるクライアントと同じようにAPIサーバーへ正式なリクエストを送るだけの立場。この理解があると、kubectlの代わりに別のツールやプログラムが同じAPIサーバーへ話しかけても同じことができる、という応用も見えてくる。", "vs": "「kubectl＝Kubernetesそのもの」という誤解に注意。kubectlはあくまでAPIサーバーへの1つの入り口（client）にすぎず、クラスタの中身の仕組みそのものではない。", "usecase": "QA目線では、CI/CDのパイプラインの中でkubectlを自動実行するとき、実際にはAPIサーバーへのリクエストを送っているだけだと理解しておくと、権限設定やエラーの切り分けがしやすくなる。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"40\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"65.0\" y=\"51\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">kubectl</text><text x=\"65.0\" y=\"66\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(client)</text><line x1=\"115\" y1=\"55\" x2=\"165\" y2=\"55\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 159 51 L 165 55 L 159 59\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"165\" y=\"25\" width=\"150\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"240.0\" y=\"44\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">APIサーバー</text><text x=\"240.0\" y=\"58\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（ここで初めて</text><text x=\"240.0\" y=\"74\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">クラスタに反映）</text></svg>", "opt": ["正解。kubectlはコマンドをAPIサーバーへの命令に変換して送るだけのclientで、コンテナを直接操作しない。", "コンテナランタイムへ直接命令を送るのはkubelet経由であり、kubectl自身が直接命令を送るわけではない。", "コマンド実行のたびにクラスタを1から作り直すことはなく、あるべき状態との差分だけが反映される。", "etcdへの書き込みはAPIサーバーが担い、kubectlが直接etcdを書き換えるわけではない。"]}'),

  ('kcna-q19', '宣言的な管理とkubectl',
   'Kubernetesの多くのコンポーネントは「あるべき状態」と「実際の状態」を常に見比べ、ずれていたら是正する、という動きを繰り返している。この考え方を一般に何と呼ぶか。',
   NULL::text,
   '["コントロールループ", "ワンタイムスクリプト", "バッチ処理の実行", "スナップショット保存"]',
   0, '[0]', 'single',
   '{"asked": "「あるべき姿と実際の姿を比べ続けて是正する」動きの名前を問う問題。", "point": "「比べる→ずれてたら直す→また比べる」の繰り返しがコントロールループ。Kubernetesの心臓部。", "kid": "Kubernetesの中の色々な仕組みは、「今どうなっているべきか」と「実際に今どうなっているか」を何度も何度も見比べて、もしズレていたら直す、という動きをずっと繰り返している。この繰り返しの仕組みをコントロールループと呼ぶ。", "eg": "エアコンの温度調節に近い。設定温度（あるべき状態）と今の室温（実際の状態）を絶えず見比べて、ズレていたら冷やしたり温めたりを繰り返す。これが止まることなく続くのがコントロールループ。", "terms": [["コントロールループ", "あるべき状態と実際の状態を比べ続け、ズレを是正する繰り返しの仕組み"], ["リコンサイル（是正）", "ズレを見つけて実際の状態をあるべき状態に近づける動作"]], "think": "なぜ一度きりの実行ではなく「ずっと繰り返す」のかがカギ。1回だけ状態を合わせても、その後ノードが落ちたりPodが消えたりすればまたズレが生まれる。ズレは時間の経過とともにいつでも起こりうるので、比べる作業を一度で終わらせず、絶え間なく繰り返す必要がある。これまで学んだ「ノードが落ちても勝手にPodが作り直される」「壊れたPodが新しく作り直される」といった挙動は、すべてこのコントロールループが裏で働いているから起きている。", "vs": "「1回実行したら終わりのスクリプト」という誤解に注意。コントロールループは一度きりの処理ではなく、あるべき状態が変わらない限り止まらずに動き続ける、という点がバッチ処理やワンタイムスクリプトと異なる。", "usecase": "QA目線では、監視ダッシュボードが常にヘルスチェックを繰り返して異常を検知し続けるのと同じ発想。1回のチェックで終わらせず、継続的に見比べ続けることの価値と重なる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"70\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"115.0\" y=\"38\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">あるべき状態</text><rect x=\"180\" y=\"20\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"225.0\" y=\"38\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">実際の状態</text><line x1=\"160\" y1=\"35\" x2=\"178\" y2=\"35\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><path d=\"M 172 31 L 178 35 L 172 39\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><line x1=\"178\" y1=\"45\" x2=\"160\" y2=\"45\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><path d=\"M 154 41 L 160 45 L 154 49\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"115\" y=\"75\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170.0\" y=\"94\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">比べてズレを是正</text><line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 69 L 170 75 L 174 69\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"125\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ずっと繰り返し続ける（コントロールループ）</text></svg>", "opt": ["正解。あるべき状態と実際の状態を比べ続け、ズレを是正し続ける仕組みがコントロールループ。", "ワンタイムスクリプトは1回実行して終わる処理で、絶え間なく繰り返すコントロールループとは性質が異なる。", "バッチ処理はまとまった作業を一括で処理する意味合いが強く、常時比べ続けて是正する繰り返しとは異なる。", "スナップショットはある時点の状態を切り取って保存したものであり、比べ続けて是正する動きそのものではない。"]}'),

  ('kcna-q20', '宣言的な管理とkubectl',
   '「あるべき状態を書いて任せる」という宣言的な管理の一番の利点として、これまで学んだ内容（ノード故障やPodの再作成など）から最も適切に説明できるものはどれか。',
   NULL::text,
   '["途中で何が起きて状態がズレても、コントロールループが自動的にあるべき状態へ近づけ続けてくれる", "宣言的に書いた設定は、一度書いたら二度と変更できなくなるので誤操作を未然に防げる", "宣言的な管理を使うと、必要なCPUやメモリの使用量を自動的に節約できるようになる", "宣言的な管理を使うと、ネットワーク通信の内容が自動的にすべて暗号化されるようになる"]',
   0, '[0]', 'single',
   '{"asked": "宣言的な管理の利点を、これまでのカテゴリの内容と結びつけて理解できているか問う問題。", "point": "宣言的管理の価値は「トラブルに強い」こと。何が起きてもコントロールループが是正し続けてくれる。", "kid": "あるべき状態さえ書いておけば、途中でノードが壊れてもPodが消えても、コントロールループが「あれ、ズレてる」と気づいて自動的に直しにいってくれる。これが宣言的な管理の一番の強み。", "eg": "エアコンの設定温度を1回決めておけば、部屋のドアが開いて温度が急に変わっても、エアコンが勝手に調整し直してくれるのと同じ。毎回手動で温度を合わせ直さなくてよい。", "terms": [["自己修復（セルフヒーリング）", "ズレや故障を検知して、あるべき状態へ自動的に戻す性質"]], "think": "なぜこれが一番の利点なのかがカギ。これまで見てきたノード故障時の自動的な作り直しや、壊れたPodの作り直しは、すべて「あるべき状態を宣言しておいたから、コントロールループが勝手に是正してくれた」結果である。もし命令的な管理（手順を毎回手で指示する方式）だったら、ノード故障のたびに人間が気づいて手作業で instructions を出し直す必要があった。宣言的管理は、この「気づいて直す」作業そのものをKubernetesに任せられる点に価値がある。", "vs": "「宣言的＝設定が固定されて変更不可になる」という誤解に注意。マニフェストはいつでも書き換えて再度あるべき状態を宣言し直せる。変更不可になるわけではない。", "usecase": "QA目線では、テスト環境の障害対応で「毎回手動で気づいて直す」運用から「宣言しておけば自動で直る」運用へ変わることは、監視・対応コストの大幅な削減につながる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"130\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"95.0\" y=\"31\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">何かが起きてズレる</text><text x=\"95.0\" y=\"45\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（ノード故障等）</text><line x1=\"95\" y1=\"50\" x2=\"95\" y2=\"67\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 91 61 L 95 67 L 99 61\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"30\" y=\"67\" width=\"130\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"95.0\" y=\"78\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コントロールループ</text><text x=\"95.0\" y=\"93\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">が自動で是正</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"77\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"255.0\" y=\"40\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">宣言的なので</text><text x=\"255.0\" y=\"54\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">人間が毎回</text><text x=\"255.0\" y=\"68\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">気づいて</text><text x=\"255.0\" y=\"82\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">指示し直さなくてよい</text></svg>", "opt": ["正解。何が起きて状態がズレても、コントロールループが自動的にあるべき状態へ近づけ続けてくれる点が最大の利点。", "マニフェストは変更不可になるわけではなく、いつでも書き換えて新しいあるべき状態を宣言し直せる。", "CPUやメモリの使用量を自動的に節約する機能ではなく、あるべき状態への是正を自動化する仕組みである。", "通信の暗号化を自動的に行う機能ではなく、あるべき状態への是正を自動化する仕組みである。"]}'),

  ('kcna-q21', 'ReplicaSetとDeployment',
   '「同じ内容のPodを常に3つ動かし続けたい」というあるべき状態を保証する役割を持つコンポーネントはどれか。',
   NULL::text,
   '["ReplicaSet（レプリカセット）", "Service（サービス）", "ConfigMap（コンフィグマップ）", "Volume（ボリューム）"]',
   0, '[0]', 'single',
   '{"asked": "指定した数のPodを維持する役割を持つコンポーネントを問う問題。", "point": "「常にN個」を保証するのがReplicaSetの仕事。数が減れば足し、増えすぎれば減らす。", "kid": "ReplicaSetは「同じ内容のPodを常に3つ」のように、決めた数のPodをキープし続ける役目を持つ。Podが1つ壊れて2つになったら、ReplicaSetが気づいて新しく1つ作り、また3つに戻す。", "eg": "水槽の魚を常に3匹に保つ役目の飼育員のようなもの。1匹弱って減ったら新しい1匹を補充し、逆に増えすぎたら間引く。", "terms": [["ReplicaSet", "指定した数のPodを常に維持するコンポーネント"], ["レプリカ数", "維持したいPodの数"]], "think": "なぜこの機能が独立したコンポーネントとして必要なのかがカギ。ここまでのカテゴリで「Podは使い捨てで、壊れたら作り直す」という考え方を学んだが、その「常に何個あるべきか」を覚えておいて監視し続ける役目を担っているのがReplicaSetである。宣言的な管理（あるべき状態を書く）とコントロールループ（比べて是正する）という土台の上に、「レプリカ数の維持」という具体的な機能として実装されているのがReplicaSet。", "vs": "「ReplicaSetがPodの中身のアプリを更新してくれる」という誤解に注意。ReplicaSetは数を維持することに専念し、アプリのバージョン更新やロールアウトの管理は次に学ぶDeploymentの役目。", "usecase": "QA目線では、負荷テストで一部のPodが落ちても全体のスループットを落とさないようにしたいとき、ReplicaSetによる自動補充がその土台になる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"15\" width=\"100\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ReplicaSet（3を維持）</text><line x1=\"128\" y1=\"41\" x2=\"128\" y2=\"58\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 124 52 L 128 58 L 132 52\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"41\" x2=\"170\" y2=\"58\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 52 L 170 58 L 174 52\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"212\" y1=\"41\" x2=\"212\" y2=\"58\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 208 52 L 212 58 L 216 52\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"108\" y=\"58\" width=\"40\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"128.0\" y=\"75\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><rect x=\"150\" y=\"58\" width=\"40\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170.0\" y=\"75\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><rect x=\"192\" y=\"58\" width=\"40\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"212.0\" y=\"75\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><text x=\"170\" y=\"105\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1つ減れば、新しく1つ作って3つに戻す</text></svg>", "opt": ["正解。指定した数のPodを常に維持する役割を持つのがReplicaSet。", "Serviceは安定した通信の窓口を提供する役割で、Podの数そのものを維持する役割ではない。", "ConfigMapは設定を保持する仕組みで、Podの数の維持とは関係がない。", "Volumeはデータを保存・共有する仕組みで、Podの数の維持とは関係がない。"]}'),

  ('kcna-q22', 'ReplicaSetとDeployment',
   'Podを直接1つ作って動かすのではなく、ReplicaSetやDeploymentを介して作ることが一般に推奨される理由として最も適切なものはどれか。',
   NULL::text,
   '["Podを直接作ると消えても誰も自動的に補充してくれないが、ReplicaSet等を介せば数の維持や作り直しが自動化されるため", "Podを直接作ると、その起動そのものにかかる速度がいつも大きく遅くなってしまうため", "Podを直接作ると、そのPodだけ利用料金の課金額が他より特別に高くなる仕組みになっているため", "Podを直接作ると、そのPodだけネットワーク通信がいっさいできなくなってしまうため"]',
   0, '[0]', 'single',
   '{"asked": "Podを直接ではなくReplicaSet/Deployment経由で作る理由を問う問題。", "point": "直接作ったPodには「面倒を見てくれる監督役」がいない。ReplicaSet経由なら自動補充・自動修復が付いてくる。", "kid": "Podを直接ポンと1つ作っただけだと、それが消えても誰も気づいて新しく作り直してはくれない。ReplicaSetやDeploymentを介して作ると、「常にこの数を維持する」という監督役がついてくるので、Podが消えても自動で補充される。", "eg": "ReplicaSetを介さず作ったPodは、保護者のいない子ども1人で外出しているようなもの。何かあっても迎えに来てくれる人がいない。ReplicaSetを介せば、常に見守ってくれる保護者付きになる。", "terms": [["ベアPod", "ReplicaSetなどの監督役を介さず直接作られたPod。壊れても自動で補充されない"]], "think": "なぜ「監督役」の有無がそれほど重要なのかがカギ。これまでのカテゴリで、Podは使い捨てで壊れることが前提の存在だと学んだ。壊れることが前提なら、壊れたときに気づいて対処してくれる仕組みが不可欠になる。ReplicaSet（やそれを内包するDeployment）はまさにその役目を担っており、これを介さずにPodを直接作ると、この自動対処の恩恵を受けられなくなる。", "vs": "「Podを直接作ってはいけない、常に禁止」という極端な誤解に注意。学習や一時的な検証目的で直接Podを作ることもあるが、本番運用で継続的に動かしたいアプリは、監督役（ReplicaSet/Deployment）を介すのが基本という理解が正確。", "usecase": "QA目線では、動作確認のためにさっと1つだけPodを直接作って試すことはあっても、実際にテスト環境を継続運用するならDeployment経由で作るのが定石になる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"130\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"85.0\" y=\"33\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">直接作ったPod</text><text x=\"85.0\" y=\"48\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（監督役なし）</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"255.0\" y=\"33\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ReplicaSet経由</text><text x=\"255.0\" y=\"48\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（監督役あり）</text><text x=\"85\" y=\"70\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">消えたら誰も補充しない</text><text x=\"255\" y=\"70\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">消えても自動で補充される</text></svg>", "opt": ["正解。Podを直接作ると自動補充の監督役がいないが、ReplicaSet等を介せば数の維持や作り直しが自動化される。", "起動速度そのものが遅くなるという性質はなく、違いは「壊れたときに自動で補充されるかどうか」にある。", "課金の仕組みはPodの作り方（直接／ReplicaSet経由）そのもので変わるものではない。", "ネットワーク通信自体は直接作ったPodでも通常どおり可能で、通信が一切できなくなるわけではない。"]}'),

  ('kcna-q23', 'ReplicaSetとDeployment',
   'DeploymentとReplicaSetの関係として最も正確なものはどれか。',
   NULL::text,
   '["DeploymentはReplicaSetを管理する、より上位の仕組みで、ローリングアップデートやロールバックといった機能を追加で提供する", "DeploymentとReplicaSetは実装が違うだけでまったく同じ機能を持つ、単なる呼び方の違いにすぎない", "逆にReplicaSetのほうがDeploymentを内部に複数持つという、入れ子になった構造になっている", "DeploymentはPodの数を維持する機能を一切持たず、ReplicaSetだけがその機能を持つ"]',
   0, '[0]', 'single',
   '{"asked": "DeploymentとReplicaSetの上下関係を問う問題。", "point": "Deploymentは「ReplicaSetの上司」。数の維持はReplicaSetに任せつつ、更新やロールバックの機能を上乗せする。", "kid": "ReplicaSetは「決めた数のPodを維持する」係。Deploymentはそのさらに上に立ち、ReplicaSetを管理しながら、「新しいバージョンに少しずつ入れ替える」「前のバージョンに戻す」といった追加の仕事もこなす、より上位の仕組み。", "eg": "ReplicaSetが「店の人数をいつも3人に保つ店長代理」だとすると、Deploymentはその店長代理に「今日から新しいユニフォームに順番に着替えさせて」と指示を出す、さらに上の本部担当に近い。", "terms": [["Deployment", "ReplicaSetを管理し、ローリングアップデートやロールバックの機能を提供する上位の仕組み"], ["ローリングアップデート", "少しずつ新しいバージョンのPodに入れ替えていく更新方法"]], "think": "なぜReplicaSetの上にさらにDeploymentを重ねるのかがカギ。ReplicaSet単体では「今のバージョンのPodを何個維持するか」しか扱えない。しかし実際の運用では「新しいバージョンへ安全に入れ替えたい」「失敗したら前のバージョンに戻したい」というニーズが必ず出てくる。Deploymentは、新旧2つのReplicaSetを内部でうまく使い分けることで、この入れ替えやロールバックを実現している。", "vs": "「ReplicaSetを直接手で操作して更新する」という誤解に注意。実務では通常Deploymentを操作し、その内部でDeploymentが自動的にReplicaSetを作り替えている。ReplicaSetを直接いじることは基本的に避ける。", "usecase": "QA目線では、新バージョンのリリース後に不具合が見つかったとき、Deploymentのロールバック機能を使えば、テストで確認済みの前バージョンへすぐ切り戻せる。", "viz": "<svg viewBox=\"0 0 340 135\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"12\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">更新・ロールバックを追加</text><rect x=\"120\" y=\"20\" width=\"100\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"38\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Deployment</text><line x1=\"170\" y1=\"48\" x2=\"170\" y2=\"65\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 59 L 170 65 L 174 59\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"120\" y=\"65\" width=\"100\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ReplicaSet</text><text x=\"170\" y=\"108\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">数の維持はReplicaSetに任せる</text></svg>", "opt": ["正解。DeploymentはReplicaSetを管理する上位の仕組みで、ローリングアップデートやロールバックを追加提供する。", "同じ呼び方違いではなく、Deploymentが追加の機能（更新・ロールバック）を持つ上位の仕組みという違いがある。", "ReplicaSetがDeploymentを内部に持つ入れ子ではなく、逆にDeploymentがReplicaSetを管理する関係である。", "Deploymentも内部でReplicaSetを介してPodの数を維持しており、その機能を持たないわけではない。"]}'),

  ('kcna-q24', 'ReplicaSetとDeployment',
   'Deploymentで新しいバージョンのアプリに更新するとき、一度に全部のPodを新バージョンへ切り替えるのではなく、少しずつ段階的に入れ替えていく標準的な更新方法を何と呼ぶか。',
   NULL::text,
   '["ローリングアップデート", "ビッグバンアップデート", "コールドスタンバイ", "サイレントアップデート"]',
   0, '[0]', 'single',
   '{"asked": "少しずつ段階的にPodを入れ替える標準的な更新方法の名前を問う問題。", "point": "一気に全部切り替えず、少しずつ・波が寄せるように入れ替えるのがローリングアップデート。", "kid": "新しいバージョンに更新するとき、いきなり全部のPodを一度に入れ替えると、切り替えの瞬間にサービスが止まってしまうかもしれない。そこで、1個ずつ・少しずつ新しいバージョンのPodに入れ替えていく方法をローリングアップデートと呼ぶ。", "eg": "お店の看板を一斉に全部つけ替えるのではなく、1つの支店ずつ順番に新しい看板へ交換していくイメージ。交換中も他の支店は営業を続けられる。", "terms": [["ローリングアップデート", "少しずつ段階的にPodを新バージョンへ入れ替えていく更新方法"]], "think": "なぜ少しずつ入れ替えるのかがカギ。全部を一気に入れ替えると、新バージョンに問題があった場合にサービス全体が止まってしまうリスクがある。少しずつ入れ替えれば、常に一定数の古いバージョンのPodが残ってサービスを支え続けるので、切り替え中もサービスが止まりにくい。この段階的な入れ替えを、Deploymentが内部で新旧2つのReplicaSetを操作しながら自動的に進めてくれる。", "vs": "「ローリングアップデート＝一瞬で切り替わる」という誤解に注意。文字どおり時間をかけて段階的に入れ替えるプロセスであり、瞬間的な切り替えではない。", "usecase": "QA目線では、新バージョンをリリースするとき、ローリングアップデートの途中で新旧両方のバージョンが同時に動いている状態が起こりうるため、その混在期間を考慮したテスト設計が必要になる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"65.0\" y=\"36\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">旧v1</text><rect x=\"110\" y=\"20\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"145.0\" y=\"36\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">旧v1</text><rect x=\"190\" y=\"20\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"225.0\" y=\"36\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">新v2</text><rect x=\"270\" y=\"20\" width=\"60\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"300.0\" y=\"36\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">新v2</text><text x=\"170\" y=\"15\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">少しずつ順番に入れ替わっていく</text><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">一気に全部ではなく、段階的に切り替える</text></svg>", "opt": ["正解。少しずつ段階的にPodを新バージョンへ入れ替えていく更新方法がローリングアップデート。", "「ビッグバンアップデート」は一度に全部を切り替えるやり方を指すことが多く、少しずつの入れ替えとは逆の考え方。", "コールドスタンバイは普段動かさない予備を待機させておく方式で、段階的な入れ替えとは異なる考え方。", "サイレントアップデートは通知なく行う更新を指す言葉で、段階的な入れ替え方法そのものを表す一般的な用語ではない。"]}'),

  ('kcna-q25', 'ReplicaSetとDeployment',
   'ローリングアップデートで新バージョンに切り替えた直後、重大な不具合が見つかった。Deploymentを使っていた場合、これに対応する典型的な機能はどれか。',
   NULL::text,
   '["ロールバック（直前の安定していたバージョンへ戻す機能）", "クラスタ全体を初期状態に完全リセットする機能", "壊れたPodのログを自動的にすべて削除する機能", "不具合のあるコンテナのソースコードを自動的に書き換えて直す機能"]',
   0, '[0]', 'single',
   '{"asked": "新バージョンに問題が見つかったときの対応機能を問う問題。", "point": "ロールバック＝「前のうまくいっていた状態に戻す」。Deploymentが履歴を覚えているから可能になる。", "kid": "新しいバージョンに切り替えたあとで問題が見つかったら、Deploymentは「1つ前のうまくいっていたバージョン」に戻すロールバックという機能を持っている。これによって、慌てず前の安定した状態にすぐ戻せる。", "eg": "服を新調して着てみたら似合わなかったとき、前に着ていたお気に入りの服にすぐ着替え直すようなもの。Deploymentは「前に着ていた服」の情報を履歴として覚えている。", "terms": [["ロールバック", "直前の安定していたバージョンへ戻す操作"], ["リビジョン履歴", "Deploymentが記憶している過去のバージョンの記録"]], "think": "なぜロールバックがそれほど簡単にできるのかがカギ。Deploymentは新しいバージョンに切り替えるたびに、その前のReplicaSet（旧バージョンの設定一式）をすぐには消さずに履歴として残している。だから問題が起きたときは、真新しくゼロから旧バージョンを作り直すのではなく、残っている履歴のReplicaSetへの切り替えを、ローリングアップデートと同じ仕組みで逆向きに進めるだけでよい。これは前のカテゴリで学んだ「宣言的な管理」の応用で、あるべき状態を「1つ前のバージョン」に書き換えるだけで済む。", "vs": "「ロールバックはクラスタ全体を初期化すること」という誤解に注意。ロールバックはあくまで対象のDeploymentのバージョンを1つ前に戻すことであり、クラスタ全体の初期化とは規模が異なる。", "usecase": "QA目線では、リリース後の監視で異常を検知した際に、原因調査より先にまずロールバックでサービスへの影響を止める、という初動対応の判断材料になる。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"25\" width=\"100\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"90.0\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">新v2</text><text x=\"90.0\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（不具合あり）</text><line x1=\"160\" y1=\"45\" x2=\"210\" y2=\"45\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 204 41 L 210 45 L 204 49\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"210\" y=\"25\" width=\"100\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"260.0\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">旧v1</text><text x=\"260.0\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（安定版へ戻す）</text><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ロールバック＝1つ前の安定バージョンへ</text></svg>", "opt": ["正解。直前の安定していたバージョンへ戻すロールバックが、この状況に対応する典型的な機能。", "クラスタ全体の初期化ではなく、対象のDeploymentのバージョンを1つ前に戻すだけの操作である。", "ログの自動削除は不具合の対応そのものではなく、ロールバックとは別の話。", "コンテナのソースコードを自動的に書き換える機能はKubernetesにはなく、あくまでバージョンの切り替えで対応する。"]}'),

  ('kcna-q26', 'Serviceとラベル・セレクタ',
   'Podは再作成されるたびにIPアドレスが変わりうる（既習）。複数のPodへアクセスする側にとって、この性質はどんな問題を引き起こしうるか。',
   NULL::text,
   '["アクセス先として特定のPodのIPを直接指定していると、Podが再作成されるたびに接続先を書き換える必要が出てきてしまう", "PodのIPアドレスが変わったとしても、アクセスする側はまったく一切影響を受けることがない", "IPアドレスが変わると、そのPodの中に保存していたデータがすべて自動的に消去されてしまう", "IPアドレスが変わると、そのPod自体がその後二度と起動できなくなってしまう仕組みである"]',
   0, '[0]', 'single',
   '{"asked": "PodのIPが変わりうる性質が引き起こす問題を問う問題。", "point": "「PodのIPは変わりうる」という前提を忘れると、アクセスする側が壊れやすくなる。だから安定した窓口が必要。", "kid": "もしアプリが「このPodのこのIPに直接アクセスする」と決め打ちしていたら、そのPodが再作成されてIPが変わったとたん、アクセスできなくなってしまう。これはPodの数が増えるほど深刻な問題になる。", "eg": "友達の家に行くのに、住所ではなく「今日たまたま止まっている車のナンバー」を頼りに向かっていたら、車が入れ替わるたびに迷子になってしまう、というイメージ。", "terms": [["安定したエンドポイント", "IPが変わっても変わらない、アクセスするための固定された窓口"]], "think": "なぜこの問題が重要なのかがカギ。以前学んだとおりPodは使い捨てで、いつ作り直されてIPが変わってもおかしくない。もしアクセスする側がPodのIPを直接覚えていたら、Podが1つ入れ替わるたびに設定を書き換える必要が生まれ、非常に壊れやすい仕組みになってしまう。この問題を解決するために、次に学ぶServiceという「変わらない窓口」の仕組みが用意されている。", "vs": "「Serviceがなくても複数Podへの安定したアクセスは自然にできる」という誤解に注意。Serviceのような仕組みがなければ、Podの入れ替わりに追従する手間が発生する。", "usecase": "QA目線では、テストコードの中にPodのIPを直接書いてしまうと、テスト環境を作り直すたびにテストが壊れる、という典型的なアンチパターンにつながる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"100\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"80.0\" y=\"38\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アクセスする側</text><text x=\"170\" y=\"15\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">直接IPを指定していると…</text><line x1=\"140\" y1=\"35\" x2=\"190\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 184 31 L 190 35 L 184 39\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"190\" y=\"15\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"235.0\" y=\"26\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod旧</text><text x=\"235.0\" y=\"40\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">IP変化前</text><text x=\"170\" y=\"70\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Podが再作成されIPが変わると、接続先を</text><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">書き換えないとアクセスできなくなる</text></svg>", "opt": ["正解。特定のPodのIPを直接指定していると、再作成でIPが変わるたびに接続先の書き換えが必要になってしまう。", "IPが変わればアクセス方法を見直す必要があり、影響を受けないというのは誤り。", "IPアドレスが変わることと、Pod内のデータが消去されることは別の話で、必ずしも連動しない。", "IPが変わってもPod自体は正常に起動・動作できる。二度と起動できなくなるわけではない。"]}'),

  ('kcna-q27', 'Serviceとラベル・セレクタ',
   'ServiceがどのPod群にアクセスを振り分けるかを決めるとき、Podの名前やIPアドレスではなく、Pod自体に貼られた「札」のようなものを目印にする。この「札」を何と呼ぶか。',
   NULL::text,
   '["ラベル", "パスワード", "証明書", "バージョン番号"]',
   0, '[0]', 'single',
   '{"asked": "ServiceがPod群を見分けるために使う目印の呼び名を問う問題。", "point": "個々のPodの名前やIPではなく、「app: front」のような貼り紙（ラベル）で仲間を見分ける。", "kid": "Podには「app: front」のような、名札（ラベル）を貼っておける。Serviceは「app: frontという名札が貼ってあるPod全員」というふうに、名札を目印にしてアクセス先の仲間を見つける。", "eg": "運動会のチーム分けで、同じ色の帽子（ラベル）をかぶっている子をまとめて1つのチームとして扱うのに近い。名前1人1人を覚える必要はなく、帽子の色だけ見ればチームが分かる。", "terms": [["ラベル", "Podなどに貼る「key: value」形式の目印"], ["セレクタ", "「このラベルが付いたものを対象にする」という指定の仕方"]], "think": "なぜ名前やIPではなくラベルを使うのかがカギ。前の設問で見たとおり、Podの名前やIPは再作成のたびに変わりうる。もしそれを頼りに仲間を見分けていたら、Podが入れ替わるたびに見分け方も書き換えなければならない。一方ラベルは「役割」を表す情報（例えばapp: front）としてPodに貼っておけるので、Podそのものが入れ替わっても、同じラベルを新しいPodに引き継がせておけば、Service側は何も変更せずに新しいPodを仲間として認識できる。", "vs": "「ラベル＝Podの固有の名前」という誤解に注意。ラベルは個体識別のためのユニークな名前ではなく、複数のPodに同じラベルを貼って「グループ」として扱うための目印である。", "usecase": "QA目線では、テスト用Podに`env: test`のようなラベルを付けておけば、本番用Podと明確に区別しながら、テスト用Pod群だけをまとめて操作・監視できる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"65.0\" y=\"31\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><text x=\"65.0\" y=\"45\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">app: front</text><rect x=\"120\" y=\"20\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"155.0\" y=\"31\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><text x=\"155.0\" y=\"45\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">app: front</text><rect x=\"210\" y=\"20\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"245.0\" y=\"31\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><text x=\"245.0\" y=\"45\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">app: back</text><line x1=\"85\" y1=\"55\" x2=\"85\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 81 69 L 85 75 L 89 69\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"155\" y1=\"55\" x2=\"155\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 151 69 L 155 75 L 159 69\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"60\" y=\"75\" width=\"140\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"130.0\" y=\"93\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Service (app: frontを選択)</text><text x=\"170\" y=\"118\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">同じラベルのPodだけを仲間として見つける</text></svg>", "opt": ["正解。Podに貼られた「key: value」形式の目印がラベルで、Serviceはこれを頼りにアクセス先を見つける。", "パスワードは認証のための秘密情報であり、Pod群を見分けるための目印ではない。", "証明書は通信の正当性を証明するための仕組みで、Pod群を見分ける目印ではない。", "バージョン番号はアプリの版数を表す情報で、そのものがラベルとして使われることはあっても、目印そのものの一般名称はラベルである。"]}'),

  ('kcna-q28', 'Serviceとラベル・セレクタ',
   'ClusterIPというタイプのServiceの特徴として最も適切なものはどれか。',
   NULL::text,
   '["クラスタの内部からのみアクセスできる、内部向けの安定した窓口を提供する", "インターネット上のどこからでも直接アクセスできる、外部公開専用の窓口である", "1つのノードのハードディスク容量を増やすための機能である", "PodのYAMLファイルの中身を自動的に暗号化する機能である"]',
   0, '[0]', 'single',
   '{"asked": "ClusterIPタイプのServiceの特徴を問う問題。", "point": "ClusterIPは「クラスタの中だけで使える内線番号」。外部には公開されない、内部向けの標準タイプ。", "kid": "ClusterIPは、クラスタの中にいる他のPodからだけアクセスできる、社内限定の窓口のようなもの。外のインターネットからは直接つながらない。何も指定しなければ、これが基本のServiceのタイプになる。", "eg": "会社の内線電話（ClusterIP）のようなもの。社内の人（クラスタ内のPod）同士は内線でかけ合えるが、社外（インターネット）から直接その内線番号にはかけられない。", "terms": [["ClusterIP", "クラスタ内部からのみアクセスできる標準的なServiceのタイプ"]], "think": "なぜ最初は「内部限定」が基本なのかがカギ。多くのPod（例えばデータベースを扱うアプリ）は、外部に直接公開する必要がなく、同じクラスタ内の他のアプリからだけアクセスされれば十分なことが多い。そこでServiceの基本タイプは、まず内部限定のClusterIPとして提供される。外部に公開したい場合は、次に学ぶ別のタイプ（NodePortやLoadBalancer）を使う、という段階的な設計になっている。", "vs": "「Serviceは常に外部公開される」という誤解に注意。実際にはServiceには複数のタイプがあり、標準のClusterIPはむしろ外部には公開されない内部向けの窓口である。", "usecase": "QA目線では、テスト対象のデータベースPodなど、外部に晒したくないコンポーネントはClusterIPで内部限定にしておくと、意図しない外部アクセスのリスクを減らせる。", "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">クラスタの中</text><rect x=\"30\" y=\"26\" width=\"280\" height=\"74\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"70\" y=\"60\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"115.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod A</text><rect x=\"200\" y=\"60\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"245.0\" y=\"78\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod B</text><line x1=\"165\" y1=\"75\" x2=\"195\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 189 71 L 195 75 L 189 79\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"46\" font-size=\"8\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"normal\">ClusterIP（内部限定の窓口）</text><text x=\"170\" y=\"130\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">クラスタの外（インターネット）からは直接届かない</text></svg>", "opt": ["正解。ClusterIPはクラスタの内部からのみアクセスできる、標準の内部向けの窓口。", "インターネットから直接アクセスできるのはNodePortやLoadBalancerなど別のタイプで、ClusterIPは内部限定である。", "ディスク容量を増やす機能ではなく、通信の窓口を提供する仕組みである。", "YAMLファイルの暗号化機能ではなく、Podへの通信を仲介する窓口の仕組みである。"]}'),

  ('kcna-q29', 'Serviceとラベル・セレクタ',
   'クラスタの外から、インターネット経由でアプリにアクセスできるようにしたい。ClusterIPだけでは実現できないこの目的のために使われる、外部公開向けのServiceタイプの組み合わせとして適切なものはどれか。',
   NULL::text,
   '["NodePortやLoadBalancerなど、外部からの入り口を提供するタイプ", "設定管理を担うConfigMapと、機密情報を扱うSecretという2種類の組み合わせ", "ノード上で動くkubeletとkube-proxyという2つのコンポーネントの組み合わせ", "ストレージに関する仕組みであるPVとPVCという2種類の組み合わせ"]',
   0, '[0]', 'single',
   '{"asked": "外部公開のために使われるServiceタイプの組み合わせを問う問題。", "point": "外部公開には内線（ClusterIP）ではなく、外線につながる別タイプ（NodePort/LoadBalancer）が要る。", "kid": "クラスタの外のインターネットからアクセスしてほしいときは、内線専用のClusterIPだけでは足りない。各ノードの決まったポート番号を外に開けるNodePortや、クラウド側の仕組みを使って外部からの入口を用意するLoadBalancerといった、外部公開向けのServiceタイプを使う。", "eg": "ClusterIPが社内の内線電話だとすると、NodePortは「会社の裏口の合鍵を配って誰でも入れるようにする」ような方法、LoadBalancerは「正式な受付窓口を1つ用意して、そこから中へ案内する」ようなイメージに近い。", "terms": [["NodePort", "各ノードの決まったポート番号を開けて外部からアクセスできるようにするタイプ"], ["LoadBalancer", "クラウド環境の負荷分散の仕組みを使って外部からの入口を提供するタイプ"]], "think": "なぜ外部公開には別のタイプが必要なのかがカギ。ClusterIPはあくまでクラスタ内部専用に設計されているため、外部からの通信を安全かつ確実に受け付ける仕組みは持っていない。NodePortやLoadBalancerは、それぞれ違う方法（ノードのポートを開ける／クラウドの負荷分散機能を使う）で、クラスタの外と中をつなぐ入口を追加で用意する。目的（内部限定か外部公開か）に応じてServiceのタイプを使い分ける、という設計になっている。", "vs": "「ConfigMap/SecretやPV/PVCも外部公開の手段」という誤解に注意。それらは設定管理やストレージのための別カテゴリの仕組みであり、外部からの通信経路を提供するものではない。", "usecase": "QA目線では、外部の負荷テストツールからテスト環境にアクセスしたいとき、ClusterIPのままではアクセスできず、NodePortやLoadBalancerタイプへの変更が必要になる、という判断につながる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"80.0\" y=\"38\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">インターネット</text><line x1=\"145\" y1=\"35\" x2=\"195\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 189 31 L 195 35 L 189 39\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"195\" y=\"20\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"255.0\" y=\"31\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">NodePort /</text><text x=\"255.0\" y=\"45\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">LoadBalancer</text><line x1=\"255\" y1=\"50\" x2=\"255\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 251 69 L 255 75 L 259 69\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"195\" y=\"75\" width=\"120\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"255.0\" y=\"93\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">クラスタ内のPod</text><text x=\"80\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ClusterIPだけでは届かない</text></svg>", "opt": ["正解。NodePortやLoadBalancerは、外部からクラスタ内へアクセスするための入口を提供するServiceタイプ。", "ConfigMapとSecretは設定・機密情報を管理する仕組みで、外部公開の入口を提供するものではない。", "kubeletとkube-proxyはノード上で動くコンポーネントであり、外部公開のためのServiceタイプではない。", "PVとPVCはストレージに関する仕組みで、外部公開のためのServiceタイプではない。"]}'),

  ('kcna-q30', 'Serviceとラベル・セレクタ',
   '同じラベルを持つPodが3つあり、それらを1つのServiceがまとめて対象にしている。このときServiceが果たしている役割として最も適切なものはどれか。',
   NULL::text,
   '["3つのPodへのアクセスを1つの安定した窓口に集約し、リクエストをその中のどれかへ振り分ける", "3つのPodのうち1つだけを選び、残りの2つを自動的に削除してしまう", "3つのPodの中身のデータをすべてかき集めて1つに合体させてしまう", "3つのPodに貼られたラベルを、自動的にすべて別々の値へ書き換えてしまう"]',
   0, '[0]', 'single',
   '{"asked": "複数Podに対するServiceの役割（窓口の集約と振り分け）を問う問題。", "point": "ゆらぐ複数のPodを、1つの固定された窓口にまとめて見せるのがServiceの本質。", "kid": "3つのPodがあっても、アクセスする側は「1つのServiceの窓口」にお願いすればよい。Serviceが裏でその3つのPodのどれかにうまく振り分けてくれる。個々のPodがどれだけ入れ替わっても、窓口（Service）は変わらない。", "eg": "コールセンターの代表番号（Service）に電話をかけると、その裏にいる複数のオペレーター（Pod）の誰かが対応してくれる。かける側は誰が出るか気にしなくてよく、いつも同じ代表番号にかければよい。", "terms": [["負荷分散", "複数のPodへアクセスを振り分けて、特定の1つに負荷が集中しないようにする働き"]], "think": "なぜ「窓口の集約」と「振り分け」の両方が大事なのかがカギ。これまでのカテゴリで、Podは複数あり、IPも変わりうる存在だと学んだ。もし窓口が1つに集約されていなければ、アクセスする側は3つのPodそれぞれの状態を把握しなければならず大変になる。Serviceが窓口を1つにまとめ、かつラベルで見つけた複数のPodへうまく振り分けることで、アクセスする側は中の詳細を意識せずに済むようになる。", "vs": "「Serviceは1つのPodだけを選んで固定する」という誤解に注意。Serviceは対象となるPod群全体へのアクセスをまとめて仲介し、通常は複数のPodへ振り分ける役割を持つ。", "usecase": "QA目線では、負荷テストで複数Podに満遍なくリクエストが分散されているかを確認することは、Serviceの振り分けが正しく機能しているかの検証そのものになる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"120\" y=\"15\" width=\"100\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170.0\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Service（1つの窓口）</text><line x1=\"128\" y1=\"41\" x2=\"128\" y2=\"58\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 124 52 L 128 58 L 132 52\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"41\" x2=\"170\" y2=\"58\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 52 L 170 58 L 174 52\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"212\" y1=\"41\" x2=\"212\" y2=\"58\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 208 52 L 212 58 L 216 52\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"108\" y=\"58\" width=\"40\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"128.0\" y=\"75\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><rect x=\"150\" y=\"58\" width=\"40\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170.0\" y=\"75\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><rect x=\"192\" y=\"58\" width=\"40\" height=\"28\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"212.0\" y=\"75\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod</text><text x=\"170\" y=\"108\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">アクセスは1つの窓口へ、裏で振り分ける</text></svg>", "opt": ["正解。複数のPodへのアクセスを1つの安定した窓口に集約し、リクエストをその中のどれかへ振り分ける。", "Serviceが対象のPodを勝手に削除して1つに絞ることはしない。複数のPod全体へアクセスを仲介する。", "各Podの中身のデータを1つに合体させる機能ではなく、通信の窓口を提供する仕組みである。", "ラベルはPod側にあらかじめ設定されているもので、Serviceが対象Podのラベルを勝手に書き換えることはしない。"]}'),

  ('kcna-q31', 'ConfigMapとSecretによる設定分離',
   '接続先のデータベースのアドレスのような設定値を、コンテナのイメージファイルの中に直接書き込んでしまうと、どんな不都合が起きやすいか。',
   NULL::text,
   '["開発環境用・本番環境用など、環境ごとに設定値が違うたびに、イメージ自体を作り直さなければならなくなる", "コンテナのイメージファイルのサイズが、書き込むたびに自動的に半分になってしまう", "コンテナが外部のネットワークに一切つながらなくなってしまう", "コンテナ内で動いているプロセスがすべて強制的に終了させられてしまう"]',
   0, '[0]', 'single',
   '{"asked": "設定値をイメージに直接書き込むことの不都合を問う問題。", "point": "設定をイメージに焼き込むと、環境が変わるたびにイメージそのものを作り直す羽目になる。", "kid": "接続先のアドレスのような設定を、コンテナのイメージ（設計図）の中に直接書いてしまうと、開発用と本番用で設定が違うたびに、イメージそのものを別々に作り直さなければならなくなって面倒。", "eg": "洋服（イメージ）にサイズ表示を縫い付けてしまうと、体型が変わるたびに服を作り直さなければならないのに近い。サイズ調整だけなら、服本体を作り直さずにベルト（外部の設定）で調節できたほうが楽。", "terms": [["設定の分離", "設定値をイメージの中に固定せず、外部から差し替えられるようにしておく考え方"]], "think": "なぜ設定を分離しておくと楽なのかがカギ。1つのアプリでも、開発・テスト・本番といった環境ごとに接続先やパラメータが異なるのが普通。設定をイメージの中に焼き込んでしまうと、環境の数だけイメージを作り分ける必要が出て、管理が煩雑になる。逆に設定を外部（ConfigMapなど）に分離しておけば、同じ1つのイメージのまま、環境ごとに外から違う設定を差し込むだけで済む。", "vs": "「設定はどこに書いても同じ」という誤解に注意。書く場所（イメージの中か、外部の仕組みか）によって、環境が変わったときの手間が大きく変わる。", "usecase": "QA目線では、同じアプリのイメージを使い回してテスト環境ごとに接続先だけ変えたい場面が多く、設定分離の考え方は日常的なテスト環境構築に直結する。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"130\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"95.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">設定をイメージに</text><text x=\"95.0\" y=\"51\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">焼き込む</text><text x=\"95\" y=\"75\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">環境ごとにイメージを作り直す必要</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"255.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">設定を外部に分離</text><text x=\"255.0\" y=\"51\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（ConfigMap等）</text><text x=\"255\" y=\"75\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">同じイメージのまま設定だけ差し替え</text></svg>", "opt": ["正解。設定値をイメージに焼き込むと、環境ごとに設定が違うたびにイメージ自体を作り直す必要が出てしまう。", "設定の書き込み方とイメージのサイズが自動的に半分になることの間に、直接の関係はない。", "設定の書き込み場所自体が、ネットワーク接続そのものを不可能にするわけではない。", "設定の書き込み場所自体が、コンテナ内のプロセスを強制終了させる原因にはならない。"]}'),

  ('kcna-q32', 'ConfigMapとSecretによる設定分離',
   'アプリの接続先URLやログレベルのような、機密性の低い一般的な設定値を、コンテナの外から渡すためのKubernetesの仕組みはどれか。',
   NULL::text,
   '["ConfigMap", "Secret", "Volume", "ReplicaSet"]',
   0, '[0]', 'single',
   '{"asked": "機密性の低い一般設定を外部から渡す仕組みの名前を問う問題。", "point": "「一般的な設定値」を外から渡す係がConfigMap。パスワードなど機密情報は次のSecretが専門。", "kid": "ConfigMapは、接続先URLやログの詳しさのような、見られても特に困らない設定値をコンテナの外から渡すための仕組み。前の設問で見た「設定をイメージに焼き込まない」を実現する主な手段の1つ。", "eg": "ConfigMapは、店舗（コンテナ）に貼る「本日の営業時間」のようなお知らせ紙。中身は誰に見られても問題ない情報で、店舗を作り直さなくても紙を貼り替えるだけで内容を変えられる。", "terms": [["ConfigMap", "機密性の低い設定値をコンテナの外から渡す仕組み"]], "think": "なぜ機密情報とそうでない情報を分けて別の仕組みにするのかがカギ。すべての設定を1つの仕組みにまとめてしまうと、パスワードのような機密情報も、ログレベルのような気軽な情報も同じ扱いになってしまい、取り扱いの注意レベルが揃わない。ConfigMapは「見られても困らない設定」専用と割り切ることで、扱いをシンプルにしている。機密情報の扱いは次に学ぶSecretという別の仕組みに任せる。", "vs": "「ConfigMapにパスワードを入れても問題ない」という誤解に注意。ConfigMapは機密情報の保護を前提に設計されておらず、パスワードのような情報はSecretで扱うのが基本。", "usecase": "QA目線では、テスト環境ごとに異なるAPIのエンドポイントURLをConfigMapで切り替えられるようにしておくと、同じテストコードを複数環境で使い回しやすくなる。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"25\" width=\"120\" height=\"55\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"90.0\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ConfigMap</text><text x=\"90.0\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">接続先URL</text><text x=\"90.0\" y=\"71\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ログレベル等</text><line x1=\"160\" y1=\"52\" x2=\"210\" y2=\"52\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 204 48 L 210 52 L 204 56\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"210\" y=\"25\" width=\"110\" height=\"55\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"265.0\" y=\"41\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ</text><text x=\"265.0\" y=\"56\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（イメージは</text><text x=\"265.0\" y=\"71\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">そのまま）</text></svg>", "opt": ["正解。機密性の低い一般的な設定値をコンテナの外から渡す仕組みがConfigMap。", "Secretはパスワードなど機密情報の取り扱い専用の仕組みで、一般設定の主な用途としてはConfigMapが基本。", "Volumeはデータの保存・共有のための仕組みであり、設定値を渡すことに特化した仕組みではない。", "ReplicaSetはPodの数を維持する仕組みであり、設定値を渡す仕組みではない。"]}'),

  ('kcna-q33', 'ConfigMapとSecretによる設定分離',
   'データベースのパスワードのような機密情報を扱うために、ConfigMapとは別に用意されているKubernetesの仕組みはどれか。また、なぜ分けられているか。',
   NULL::text,
   '["Secret。パスワードのような機密情報は、一般設定と同じ扱いにせず、取り扱いに注意が必要な情報として区別するために分けられている", "Volume。機密情報は必ずディスクの空き容量を大量に消費するため、専用のストレージ機能が必要になるから", "Service。機密情報は必ずインターネット経由でなければやり取りできない決まりになっているため", "特に分けられているわけではなく、機密情報もConfigMapにそのまま書き込むのが標準的で推奨される方法である"]',
   0, '[0]', 'single',
   '{"asked": "機密情報専用の仕組み（Secret）とその存在理由を問う問題。", "point": "機密情報は「別扱いする」ための専用の仕組みSecretが用意されている。一般設定（ConfigMap）と同列に置かない。", "kid": "パスワードのような、見られたら困る情報は、ConfigMapとは別のSecretという仕組みで扱う。同じ「設定」でも、機密かどうかで置き場所を分けることで、扱いに注意すべき情報だとひと目で分かるようにしている。", "eg": "普通のお知らせ紙（ConfigMap）と、鍵付きの金庫（Secret）を分けて置いておくイメージ。どちらも「情報を保管する」点は同じだが、金庫のほうは特別な注意を払って扱う必要がある。", "terms": [["Secret", "パスワードなど機密情報を扱うための仕組み"]], "think": "なぜ同じ「設定を外から渡す」仕組みなのにConfigMapとSecretを分けるのかがカギ。もし機密情報も一般設定も同じ1つの仕組みで扱っていたら、うっかり機密情報を気軽に扱ってしまう事故が起きやすくなる。ConfigMapとは別にSecretという専用の入れ物を用意することで、「これは機密情報だから特別に注意して扱う」という区別を、仕組みのレベルではっきりさせている。", "vs": "「Secretに入れれば自動的に強力に暗号化されて安全」という思い込みに注意。Secretは機密情報として区別して扱う仕組みではあるが、具体的な保護の強さは環境設定にも依存するため、「区別する仕組み」という理解を軸にする。", "usecase": "QA目線では、テスト用のAPIキーやDB接続情報をうっかりConfigMapや平文で扱ってしまうミスは典型的なセキュリティ上の見落としになるため、Secretを使う習慣が重要になる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"130\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"95.0\" y=\"33\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ConfigMap</text><text x=\"95.0\" y=\"48\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（一般設定）</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#8b5cf6\" stroke-width=\"1\"/><text x=\"255.0\" y=\"33\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Secret</text><text x=\"255.0\" y=\"48\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（機密情報）</text><text x=\"170\" y=\"70\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">同じ「外から渡す」仕組みでも、機密かどうかで分ける</text></svg>", "opt": ["正解。機密情報用の仕組みはSecretで、一般設定と区別して取り扱いに注意すべき情報として分けられている。", "Secretが用意されている理由はディスク容量の話ではなく、機密情報を区別して扱うためである。", "機密情報のやり取りがインターネット経由に限られるという制約はなく、Serviceとは別の話である。", "機密情報をConfigMapにそのまま書くことは推奨されず、専用のSecretを使うのが標準的な考え方である。"]}'),

  ('kcna-q34', 'ConfigMapとSecretによる設定分離',
   'ConfigMapやSecretに書いた設定値は、最終的にどのようにコンテナへ渡されるか。最も適切な説明はどれか。',
   NULL::text,
   '["環境変数として渡したり、ファイルとしてPodにマウントしたりする形で、コンテナから読み取れるようにする", "コンテナの中にあるソースコードのファイルを、直接書き換えることで反映される仕組みになっている", "設定値はコンテナには一切渡されることがなく、Kubernetesの内部だけで完結してしまう", "設定値を反映するには、必ずコンテナのイメージそのものを毎回作り直す必要がある"]',
   0, '[0]', 'single',
   '{"asked": "ConfigMap/Secretの設定値がコンテナへ渡される具体的な方法を問う問題。", "point": "渡し方は主に2通り：環境変数として渡す、またはファイルとしてマウントする。どちらもコンテナの外から読み込ませる形。", "kid": "ConfigMapやSecretに書いた設定は、コンテナの中の環境変数として渡されたり、まるでファイルが置いてあるかのようにPodの中に見せかけられたりする。どちらの方法でも、コンテナの中のアプリはその値を「外から渡された」ものとして読み取れる。", "eg": "楽屋（コンテナ）にメモを届ける方法が2通りあるようなもの。1つは口頭で耳打ちする方法（環境変数）、もう1つはメモを机の上に置いておく方法（ファイルとしてマウント）。どちらも本人（コンテナ内のアプリ）が中身を確認できる。", "terms": [["環境変数", "プログラムが起動時に読み取れる、外部から渡された値の入れ物"], ["マウント", "外部のデータを、あたかもコンテナ内のファイルであるかのように見せる仕組み"]], "think": "なぜ2通りの渡し方が用意されているのかがカギ。アプリによって、設定の読み込み方の作法が違う（環境変数を読むように作られているアプリもあれば、設定ファイルを読むように作られているアプリもある）。ConfigMap/Secretがどちらの渡し方にも対応していることで、既存のアプリの作りを変えずに、外部化された設定を柔軟に読み込ませられる。この「外から読み込ませる」という発想は、この節の最初に学んだ「設定をイメージに焼き込まない」という目的をそのまま実現する手段になっている。", "vs": "「ConfigMap/Secretの値を反映するにはイメージを毎回作り直す必要がある」という誤解に注意。むしろイメージは変更せず、外部から値を差し込むだけで済む点がこの仕組みの利点である。", "usecase": "QA目線では、既存のテスト対象アプリの作りを変えずに、テスト環境用の設定だけをConfigMap経由の環境変数で差し替える、という使い方が典型的。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"130\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"95.0\" y=\"38\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ConfigMap / Secret</text><line x1=\"170\" y1=\"35\" x2=\"190\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 184 31 L 190 35 L 184 39\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"190\" y=\"10\" width=\"130\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"255.0\" y=\"26\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">環境変数として</text><line x1=\"170\" y1=\"75\" x2=\"190\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 184 71 L 190 75 L 184 79\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"190\" y=\"62\" width=\"130\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"255.0\" y=\"71\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ファイルとして</text><text x=\"255.0\" y=\"85\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">マウント</text><text x=\"90\" y=\"110\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コンテナのイメージ自体は変更しない</text></svg>", "opt": ["正解。環境変数として渡したり、ファイルとしてPodにマウントしたりする形でコンテナから読み取れるようにする。", "ソースコードのファイルを直接書き換える仕組みではなく、外部から値を読み込ませる仕組みである。", "設定値は最終的にコンテナ側から読み取れる形で渡され、Kubernetes内部だけで完結するものではない。", "イメージを毎回作り直す必要はなく、イメージはそのままで設定だけを外から差し込める点が利点である。"]}'),

  ('kcna-q35', 'ConfigMapとSecretによる設定分離',
   'ConfigMapとSecretの違いとして、最も適切に説明しているものはどれか。',
   NULL::text,
   '["どちらも設定値を外部から渡す仕組みだが、ConfigMapは機密性の低い一般設定向け、Secretは機密情報向けという用途の違いがある", "ConfigMapは設定を渡す仕組みだが、Secretは設定を渡す仕組みではなく、Podの数を維持し続ける仕組みである", "ConfigMapとSecretは名前が違うだけの表記ゆれであり、内部の機能や用途にはまったく違いが存在しない", "ConfigMapはPodの外部公開に使う仕組みで、Secretは設定を渡す仕組みという、まったく別分野の機能である"]',
   0, '[0]', 'single',
   '{"asked": "ConfigMapとSecretという2つの似た仕組みの違いを、明示的に区別できるか問う問題。", "point": "両方とも「外から設定を渡す」役割は同じ。違うのは「機密情報かどうか」という中身の性質だけ。", "kid": "ConfigMapもSecretも、どちらも「コンテナの外から設定値を渡す」という同じ役割を持つ。違うのは中身の性質で、ConfigMapは見られても困らない一般設定向け、Secretはパスワードのような機密情報向け、という使い分け。", "eg": "ConfigMapは掲示板に貼るお知らせ、Secretは鍵付きロッカーに入れる貴重品、というイメージ。どちらも「情報を保管して必要なときに渡す」役割は同じだが、扱う中身の重要度が違う。", "terms": [["ConfigMap", "機密性の低い一般設定を渡す仕組み"], ["Secret", "パスワードなど機密情報を渡す仕組み"]], "think": "なぜこの2つをはっきり区別できることが大事なのかがカギ。このカテゴリを通して学んできたとおり、両者は「設定をコンテナのイメージに焼き込まず、外部から渡す」という同じ目的のために用意された仲間の仕組みである。違いは唯一、扱う情報が機密かどうかという点だけ。この理解があれば、「パスワードをうっかりConfigMapに書いてしまう」といった、実務でありがちなミスも避けやすくなる。", "vs": "「用途がまったく別分野」という誤解に注意。両者はどちらも「設定を外部から渡す」という共通の役割を持ち、その中で機密性によって使い分ける、近い親戚のような関係にある。", "usecase": "QA目線では、テスト設定を見直すときに「これはConfigMapに書いていい内容か、Secretに書くべき内容か」を毎回判断する習慣が、意図しない情報漏えいを防ぐ第一歩になる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"60\" y=\"15\" width=\"220\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"170.0\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">共通点：外部から設定を渡す仕組み</text><rect x=\"30\" y=\"55\" width=\"130\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"95.0\" y=\"68\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ConfigMap</text><text x=\"95.0\" y=\"83\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">一般設定向け</text><rect x=\"190\" y=\"55\" width=\"130\" height=\"34\" rx=\"6\" fill=\"none\" stroke=\"#8b5cf6\" stroke-width=\"1\"/><text x=\"255.0\" y=\"68\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Secret</text><text x=\"255.0\" y=\"83\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">機密情報向け</text><text x=\"170\" y=\"108\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">違いは「機密情報かどうか」だけ</text></svg>", "opt": ["正解。どちらも設定を外部から渡す仕組みで、機密性の低い一般設定向けか機密情報向けかという用途の違いがある。", "SecretもConfigMapと同じく設定を渡す仕組みであり、Podの数を維持するReplicaSetとは別の役割を持つ。", "扱う情報の機密性という点で用途の違いがあり、まったく同一の機能ではない。", "ConfigMapは外部公開のための仕組みではなく、Secretと同じく設定を渡すための仕組みである。"]}'),

  ('kcna-q36', 'Volumeとデータの永続化',
   'linux-basicsの`コンテナの正体`で学んだとおり、コンテナのファイルシステムは基本的に使い捨てである。この性質がPodにも当てはまるとすると、何が起きるか。',
   NULL::text,
   '["コンテナ（Pod）が再作成されると、その中に書き込んだファイルは特別な対策をしない限り失われる", "コンテナのファイルシステムは使い捨てのはずだが、Podになった瞬間から自動的に永久保存されるようになる", "コンテナのファイルシステムはそもそも書き込みができない仕組みのため、この性質は無関係である", "コンテナが使い捨てになるのはPodの外にあるときだけで、Pod内のコンテナには一切当てはまらない"]',
   0, '[0]', 'single',
   '{"asked": "コンテナのファイルシステムが使い捨てであることが、Podにも当てはまることを理解できているか問う問題。", "point": "コンテナが使い捨てなら、その中に書いたファイルも使い捨て。何もしなければPodの再作成でデータは消える。", "kid": "linux-basicsで「コンテナのファイルシステムは使い捨て」と学んだのと同じことが、Pod（コンテナの入れ物）にもそのまま当てはまる。つまり、何も対策しなければ、Podが再作成されたときに中に書いたファイルは消えてしまう。", "eg": "ホワイトボードに書いたメモ（コンテナ内のファイル）は、ホワイトボード（コンテナ）を新品に交換すると消えてしまう。新しいホワイトボードには前のメモは引き継がれない。", "terms": [["エフェメラルストレージ", "コンテナやPodと一緒に消えてしまう、使い捨てのストレージ"]], "think": "なぜこの性質を思い出す必要があるのかがカギ。Podは以前のカテゴリで学んだとおり、壊れたら直すのではなく作り直される使い捨ての存在だった。その中のコンテナのファイルシステムも同じく使い捨てなので、何も対策をしなければ、Podが作り直されるたびに中のデータもリセットされてしまう。この問題を解決するために、次に学ぶVolumeという「外部にデータを逃がす」仕組みが必要になる。", "vs": "「Podになれば自動的にデータが永続化される」という誤解に注意。Podという単位でまとめても、明示的にVolumeのような仕組みを使わない限り、データは使い捨てのままである。", "usecase": "QA目線では、テスト実行中に生成したログやレポートファイルをコンテナ内にだけ置いていると、Podが再作成された瞬間に消えてしまう、というありがちな落とし穴につながる。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"20\" width=\"100\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"90.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod（旧）</text><text x=\"90.0\" y=\"51\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">データA</text><text x=\"90\" y=\"72\" font-size=\"8\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">再作成で消える</text><line x1=\"150\" y1=\"40\" x2=\"200\" y2=\"40\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 194 36 L 200 40 L 194 44\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"200\" y=\"20\" width=\"100\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"250.0\" y=\"36\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod（新）</text><text x=\"250.0\" y=\"51\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">データなし</text></svg>", "opt": ["正解。コンテナ（Pod）が再作成されると、特別な対策をしない限り中に書き込んだファイルは失われる。", "Podになったからといって自動的に永久保存されるわけではなく、使い捨ての性質はそのまま引き継がれる。", "コンテナのファイルシステムには通常書き込みができ、その書き込んだ内容が使い捨てになる点が問題になる。", "コンテナが使い捨てである性質はPodの中のコンテナにもそのまま当てはまる。"]}'),

  ('kcna-q37', 'Volumeとデータの永続化',
   'データベースのように「消えては困るデータ」を扱うアプリをPodで動かす場合、前の設問で見た「使い捨て」の性質のままだと、どんな不都合が起きるか。',
   NULL::text,
   '["Podが再作成されるたびに、それまで保存していたはずのデータが消えてしまい、データベースとして使い物にならなくなる", "Podが再作成されると、データベース全体の処理速度だけがわずかに遅くなるだけで済む", "Podが再作成されると、そのデータベースへの接続だけができなくなるが、データ自体は無事に残り続ける", "使い捨ての性質は、データベースのようなアプリの種類によって自動的に無効化されるため、特に問題は起きない"]',
   0, '[0]', 'single',
   '{"asked": "使い捨ての性質が「消えては困るデータ」を扱うアプリにとって深刻な問題になることを問う問題。", "point": "使い捨てのままデータベースを動かすのは致命的。この問題への答えが次のVolumeという仕組み。", "kid": "データベースのように、ずっと覚えておいてほしいデータを扱うアプリを、何も対策せずにPodでそのまま動かすと、Podが再作成されるたびにこれまで貯めたデータが全部消えてしまい、まったく使い物にならなくなってしまう。", "eg": "取引の記録をずっと保管してほしい金庫が、店舗（Pod）を建て替えるたびに空っぽの新品に入れ替わってしまうようなもの。これでは金庫としての役目を果たせない。", "terms": [["ステートフルなアプリ", "データベースのように、覚えておくべき状態（データ）を持つアプリ"]], "think": "なぜこの問題がとくに深刻なのかがカギ。すべてのアプリが「消えても困らないデータ」だけを扱うわけではない。データベースのようなアプリは、まさに「データを覚え続けること」自体が存在意義であり、そこが使い捨てになってしまうと、アプリとしての価値が根本から失われる。この深刻な問題に対する解決策として、次の設問で学ぶVolumeという「Podの外側にデータを逃がす」仕組みが用意されている。", "vs": "「使い捨ての性質はアプリによって自動的に無効化される」という誤解に注意。アプリの種類に関わらず、明示的にVolumeなどの対策をしない限り、使い捨ての性質はそのまま適用される。", "usecase": "QA目線では、テスト用のデータベースPodを使うとき、テストの前提データが再作成のたびに消えてしまうと再現性のあるテストが組めなくなるため、Volumeによる永続化が重要になる。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"25\" width=\"260\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"170.0\" y=\"44\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">データベースPod（使い捨てのまま）</text><line x1=\"170\" y1=\"55\" x2=\"170\" y2=\"72\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 66 L 170 72 L 174 66\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">再作成のたびにデータが全部消える＝致命的</text></svg>", "opt": ["正解。Podが再作成されるたびにデータが消え、データベースとして使い物にならなくなる。", "起きるのは速度の低下ではなく、データそのものが失われるというより根本的な問題である。", "接続だけができなくなるのではなく、データ自体が失われる点が問題の本質である。", "使い捨ての性質はアプリの種類によって自動的に無効化されるわけではなく、対策なしでは常に起こりうる。"]}'),

  ('kcna-q38', 'Volumeとデータの永続化',
   'Podが再作成されてもデータを消さずに残しておきたいとき、Kubernetesで使われる仕組みは何か。',
   NULL::text,
   '["Volume。Pod（コンテナ）の外側にデータの置き場所を用意し、Podが作り直されても同じデータを参照し続けられるようにする", "ラベル。Podにラベルを貼っておくだけで、自動的にデータが消えなくなる仕組みになっている", "kubectl。コマンドを打つたびに、その実行内容が自動的にバックアップとして保存されていく", "namespace。namespaceを分けておくだけで、データがすべて自動的に永続化されるようになる"]',
   0, '[0]', 'single',
   '{"asked": "Podの再作成にもデータを残すための仕組み（Volume）を問う問題。", "point": "Podやコンテナが何度入れ替わっても、Volumeという「外の置き場所」だけは残り続ける。", "kid": "Volumeは、Podの中ではなく外側にデータの置き場所を用意しておく仕組み。Pod自体が使い捨てで作り直されても、Volumeという外の置き場所は残り続けるので、新しいPodも同じデータを見に行ける。", "eg": "ロッカー（Volume）に荷物を預けておけば、電車（Pod）が新しい車両に入れ替わっても、駅のロッカーはそのまま残っていて、いつでも同じ荷物を取り出せる、というイメージ。", "terms": [["Volume", "Podの外側にデータを保存し、Podが作り直されてもデータを残せる仕組み"]], "think": "なぜ「外側に置く」という発想が解決策になるのかがカギ。ここまでの設問で見たとおり、問題の根本は「Podの中にデータを置いていると、Podと運命を共にして消えてしまう」ことにあった。ならば、データをPodの中ではなく外側の別の場所に置いておけば、Pod自体が入れ替わってもデータだけは影響を受けずに残り続けられる。Volumeはこの「置き場所をPodの外に出す」という考え方をそのまま実現した仕組み。", "vs": "「ラベルを貼るだけでデータが永続化される」という誤解に注意。ラベルはPodを見分けるための目印であり、データの保存場所そのものを提供する仕組みではない。", "usecase": "QA目線では、テストで生成したログやレポートを、テスト用Podが再作成されても失わずに残しておきたいとき、Volumeによる外部保存を検討する対象になる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"110\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"85.0\" y=\"44\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod(旧)</text><rect x=\"190\" y=\"20\" width=\"110\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"245.0\" y=\"44\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Pod(新)</text><rect x=\"90\" y=\"75\" width=\"160\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170.0\" y=\"94\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Volume（外の置き場所）</text><line x1=\"85\" y1=\"60\" x2=\"85\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 81 69 L 85 75 L 89 69\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"245\" y1=\"60\" x2=\"245\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 241 69 L 245 75 L 249 69\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"118\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Podが入れ替わってもVolumeは残る</text></svg>", "opt": ["正解。Podの外側にデータの置き場所を用意し、Podが作り直されても同じデータを参照し続けられるのがVolume。", "ラベルはPodを見分ける目印であり、データを永続化する仕組みではない。", "kubectlはAPIサーバーへ命令を送る道具であり、自動バックアップの仕組みではない。", "namespaceはクラスタ内のリソースを論理的に区切る仕組みであり、データを自動で永続化する機能ではない。"]}'),

  ('kcna-q39', 'Volumeとデータの永続化',
   '永続的なストレージを扱うとき、KubernetesにはPV（PersistentVolume）とPVC（PersistentVolumeClaim）という2つの言葉が出てくる。両者の関係として最も適切なものはどれか。',
   NULL::text,
   '["PVは実際に用意されたストレージの資源そのもの、PVCはアプリ側が出す「これくらいのストレージが欲しい」という要求（申込み）", "PVとPVCは実装が違うだけでまったく同じものを指しており、単なる略し方の違いにすぎない", "PVCがまずストレージの実体そのものを作り、その後PVがそれを削除するという順番の関係である", "PVはPodの数を管理する機能、PVCはネットワーク設定を管理する機能で、ストレージとは無関係である"]',
   0, '[0]', 'single',
   '{"asked": "PVとPVCという似た2つの略語の役割の違いを問う問題。", "point": "PVは「用意されている部屋そのもの」、PVCは「この広さの部屋がほしい、という申込書」。", "kid": "PV（PersistentVolume）は、実際に用意されているストレージという「部屋」そのもの。PVC（PersistentVolumeClaim）は、アプリ側が「これくらいの広さの部屋がほしい」と出す申込書のようなもの。申込書（PVC）が出されると、条件に合う部屋（PV）と結び付けられる。", "eg": "PVが「実際にある賃貸物件」、PVCが「この条件の部屋を探しています、という入居申込書」に近い。申込書と物件がマッチすると、入居（結び付け）が成立する。", "terms": [["PV(PersistentVolume)", "実際に用意された永続的なストレージの資源そのもの"], ["PVC(PersistentVolumeClaim)", "アプリ側が出すストレージ利用の要求（申込み）"]], "think": "なぜ「実体」と「要求」を分けて考えるのかがカギ。この設計により、アプリを作る側（Podのマニフェストを書く人）は、ストレージの実体がどんなハードウェアでどこにあるかを細かく知らなくても、「これくらいの容量が欲しい」というPVCさえ書けば、あとはKubernetesが適切なPVと結び付けてくれる。これは、以前学んだ宣言的な管理（あるべき状態だけを書いて、実現方法は任せる）と同じ発想が、ストレージの世界にも応用されたものと理解できる。", "vs": "「PVCが先にストレージの実体を作る」という順序の誤解に注意。PVC自体はあくまで要求（申込み）であり、実体（PV）はあらかじめ用意されているか、要求に応じて別途用意される、という関係になる。", "usecase": "QA目線では、テスト用データベースPodのマニフェストにPVCを書いておけば、その裏でどんなストレージが割り当てられているかを細かく意識せずにテスト環境を組み立てられる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"25\" width=\"130\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"95.0\" y=\"34\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">PVC</text><text x=\"95.0\" y=\"48\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「これくらい欲しい」</text><text x=\"95.0\" y=\"62\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">という要求</text><line x1=\"165\" y1=\"45\" x2=\"210\" y2=\"45\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 204 41 L 210 45 L 204 49\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"210\" y=\"25\" width=\"100\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"260.0\" y=\"34\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">PV</text><text x=\"260.0\" y=\"48\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実際のストレージ</text><text x=\"260.0\" y=\"62\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">資源そのもの</text><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">要求（PVC）と実体（PV）が結び付く</text></svg>", "opt": ["正解。PVは実際に用意されたストレージの資源そのもの、PVCはアプリ側が出すストレージ利用の要求。", "略し方の違いではなく、実体（PV）と要求（PVC）という異なる役割を持つ別の概念である。", "PVCが先にPVを削除するという関係ではなく、要求と実体が結び付けられる関係である。", "どちらも永続的なストレージに関する仕組みであり、Podの数やネットワーク設定を管理するものではない。"]}'),

  ('kcna-q40', 'Volumeとデータの永続化',
   'QAの実務経験を踏まえると、自動テストで使う「テスト対象アプリを動かすだけのPod」と、「テストの前提データを持つデータベースのPod」とでは、Volumeによる永続化の必要性はどう違うと考えられるか。',
   NULL::text,
   '["テスト対象アプリのPodは使い捨てでよいことが多いが、前提データを持つデータベースのPodはVolumeでの永続化が重要になりやすい", "どちらのPodも永続化の必要性にはまったく差がなく、常にまったく同じように扱えばよいだけである", "テスト対象アプリのPodにこそ必ずVolumeが必要になり、逆にデータベースのPodのほうには不要になる", "自動テストの文脈では、Podという単位そのものを使うことが一切ないため、この違いを考える必要は生じない"]',
   0, '[0]', 'single',
   '{"asked": "ステートレスなPodとステートフルなPodで永続化の必要性が異なることを、QAの実務文脈で理解できているか問う問題。", "point": "「消えて困るデータを持っているかどうか」で永続化の要不要が変わる。テスト対象アプリ自体は使い捨てでよいことが多い。", "kid": "テスト対象のアプリを動かすだけのPodは、たいてい中に大事なデータを溜め込んでいないので、再作成されて消えても特に困らないことが多い。一方、テストの前提データ（例えば「このユーザーが登録済み」という状態）を持つデータベースのPodは、データが消えるとテストの前提が崩れてしまうので、Volumeでの永続化がより重要になる。", "eg": "使い捨てのテスト用紙（アプリのPod）は毎回新品に取り替えても困らないが、実験結果を書き溜めているノート（データベースのPod）は、勝手に新品に差し替えられると困る、というイメージ。", "terms": [["ステートレス", "自分の中に重要な状態（データ）を持たず、いつ作り直されても困らない性質"], ["ステートフル", "重要な状態（データ）を持ち、作り直されるとその状態を失ってしまう性質"]], "think": "なぜこの区別がQA実務で大事なのかがカギ。テスト自動化の環境を組むとき、すべてのPodに一律でVolumeを付けるかどうか迷うことがある。この節で学んだ考え方（消えて困るデータを持つかどうか）を当てはめれば、テスト対象アプリのような使い捨てでよいPod（ステートレス）にはVolumeが不要なことが多く、テストの前提データを持つPod（ステートフル）にはVolumeが重要、という判断基準が立てられる。この判断力こそが、単なる暗記ではなく仕組みを理解して応用する力にあたる。", "vs": "「Volumeは常にすべてのPodに付けるべきもの」という誤解に注意。ステートレスなPodにまで無条件にVolumeを付けると、かえって管理が複雑になることがある。必要性を見極めることが大切。", "usecase": "QA目線そのものの設問。テスト環境の設計時に、どのPodにVolumeが必要かを判断する基準として、ステートレスかステートフルかという観点を持てるようになることが、この第一期の総まとめにあたる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"20\" width=\"130\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"95.0\" y=\"36\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">テスト対象アプリPod</text><text x=\"95.0\" y=\"50\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（ステートレス）</text><text x=\"95\" y=\"75\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">使い捨てでよいことが多い</text><rect x=\"190\" y=\"20\" width=\"130\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"255.0\" y=\"36\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">データベースPod</text><text x=\"255.0\" y=\"50\" font-size=\"7\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（ステートフル）</text><text x=\"255\" y=\"75\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Volumeでの永続化が重要</text><text x=\"170\" y=\"110\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">「消えて困るデータを持つか」で判断する</text></svg>", "opt": ["正解。テスト対象アプリは使い捨てでよいことが多いが、前提データを持つデータベースPodはVolumeでの永続化が重要になりやすい。", "持っているデータの性質（消えて困るかどうか）によって必要性は変わり、常に同じ扱いでよいわけではない。", "むしろ消えて困るデータを持つデータベースのPodのほうが永続化の必要性は高く、逆の説明になっている。", "自動テストの文脈でもKubernetesを使う場合はPodという単位でアプリやデータベースが動くため、この違いを考える必要がある。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'kcna'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;